  FT["PH-H5836"] = {"id":"PH-H5836","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7348_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省 Batad 市镇 Batad 国立中学与 Batad 国立农业与职业中学合并整合为名为 Batad 理工学院的理工学院并为其拨款的法案","en":"An Act Merging and Integrating the Batad National High School and the Batad National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, Into a Polytechnic College to Be Known as the Batad Polytechnic College, and Appropriating Funds Therefor","orig":"An Act Merging and Integrating the Batad National High School and the Batad National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, Into a Polytechnic College to Be Known as the Batad Polytechnic College, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 7348","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7348_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5836-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Batad National High School and the Batad National Agricultural and Vocational High School are hereby merged and integrated into a polytechnic college to be known as the Batad Polytechnic College."}},{"id":"PH-H5836-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets, fixed and movable, personnel, records and documents of the Batad National High School and the Batad National Agricultural and Vocational High School in the Municipality of Batad, Province of lloilo, as well as their liabilities shall be transferred to the Batad Polytechnic College: Provided, however, That the positions, rights and security of tenure of personnel employed therein pursuant to existing laws prior to the integration of the Batad National High School and the Batad National Agricultural and Vocational High School into the Batad Polytechnic College are not impaired."}},{"id":"PH-H5836-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to the current appropriations of the Batad National High School and the Batad National Agricultural and Vocational High School, the amount needed to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5836-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Education, Culture and Sports shall take the necessary steps for the immediate implementation of this Act."}},{"id":"PH-H5836-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All laws, presidential decrees, executive orders, rules and regulations contrary to or inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly"}},{"id":"PH-H5836-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Merging and Integrating the Batad National High School and the Batad National Agricultural and Vocational High School in the Municipality of Batad, Province of Iloilo, Into a Polytechnic College to Be Known as the Batad Polytechnic College, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5837"] = {"id":"PH-H5837","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7349_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Silangan Airways, Inc. 设立、运营和维护国内与国际航空客运、邮件、货物与财产运输服务的特许经营权法案","en":"An Act Graniting to Silangan Airways, Inc., a Franchise to Establish, Operate and Maintain Transport Services for Carriage of Passengers, Mails, Goods and Property By Air Both Domestic and International","orig":"An Act Graniting to Silangan Airways, Inc., a Franchise to Establish, Operate and Maintain Transport Services for Carriage of Passengers, Mails, Goods and Property By Air Both Domestic and International"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7349","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7349_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5837-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Silangan Airways, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, operate and and maintain transport services for carriage of passengers, mails, goods and property by air both domestic and international.\nAir transport services shall include the maintenance and operation of hangars and aircraft service stations and facilities and other services of similar nature which may be necessary, convenient or useful as an auxiliary to aircraft transportation.\nThe grantee shall have the right at its terminals and landing fields, as well as in its aircraft, to construct, operate and maintain stations or transmitting sets for wireless telegraphy and direction finding, and other radio aids to air navigation, using wavelengths in accordance with the rules and regulations made from time to time by the proper agencies of the Government. The wireless communication facilities shall be used solely for receiving and transmitting weather forecasts and other matters in connection with the grantee's services."}},{"id":"PH-H5837-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Prior Approproval of the Civil Aeronautics Board. - The grantee shall secure from the Civil Aeronautics Board the appropriate permits and licenses for its operations.\nAll aircraft used by the grantee and the flight-crew members operating such aircraft shall be licensed by the Government of the Philippines and together with its accessories and equipment shall at all times be in airworthy condition. They shall be equipped with radio communications, safety and other equipment and shall be operated and maintained in accordance with the regulations and technical requirements of the Air Transportation Office or such other regulatory body as the Government may prescribe for this purpose.\nThe grantee's equipment and the operation of such equipment shall at all times be subject to inspection and regulation by the Air Transportation Office.\nThe grantee shall comply with the provisions of Republic Act Numbered Seven hundred and seventy-six, and the regulations promulgated thereunder from time to time."}},{"id":"PH-H5837-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Responsibility to the Public. - Excepting cases of force majeure and whenever weather conditions permit, the grantee shall maintain scheduled and/or non-scheduled and/or charter air transport services to any and all points and places throughout the Philippines and between the Philippines and other countries at such frequencies as traffic needs may require: Provided, however, That at least twenty-five percent (25%) of all its frequencies shall be for the domestic market."}},{"id":"PH-H5837-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Rates for Services. - The grantee shall fix just and reasonable rates for the transportation of passengers, malls, goods and freight, subject to the regulations and approval of the Civil Aeronautics Board and other proper regulatory agencies of the Government."}},{"id":"PH-H5837-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of forty (40) years from the date of the approval of this Act, unless sooner revoked or cancelled. In the event that the grantee falls to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5837-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Landing Facilities. - The grantee may use the landing and other airport facilities on land and water as may be maintained or owned by the Government within the Philippines on the grantee's lines subject to such terms and conditions, restrictions and national policy considerations as the Philippine Government may prescribe, and reciprocally, the Philippine Government shall have the right to use the landing and other airport facilities as may be maintained or owned by the grantee in the Philippines."}},{"id":"PH-H5837-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contracts. - The grantee is authorized to enter into transportation contracts with the Philippine Government, including the carrying of mail, upon terms and conditions to be mutually agreed upon. The grantee shall give preferential consideration to contracts with the Philippine Government.\nThe grantee may likewise enter into transportation maintenance and/or servicing contracts, and such other contracts relating to air transport with other foreign-owned airlines particularly with those who have international routes."}},{"id":"PH-H5837-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Right of Government. - In case of war, insurrection, domestic trouble, public calamity, or national emergency, the Philippine Government, upon order of the President, shall have the right to take over and operate the equipment of the grantee, paying for its use or damages."}},{"id":"PH-H5837-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Equity Participation. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchange of at least thirty percent (30%) of its common stock within a period of ten (10) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5837-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the operation of the services under the franchise hereby granted."}},{"id":"PH-H5837-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Tax Provisions. - The grantee shall pay to the Philippine Government during the life of this franchise, a franchise tax of five percent (5%) of the gross revenues derived by the grantee from transport operations.\nIn the event any competing individual, partnership and corporation receives and enjoys tax privileges which tend to place the grantee herein at any disadvantage, then such provisions shall be deemed part hereof and shall operate equally in favor of the grantee.\nThe grantee shall, however, be subject to income tax levied under Title II of the National Internal Revenue Code, as amended, and tax on its real property under existing laws on revenues earned from activities other than air transportation."}},{"id":"PH-H5837-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Interpretation of Franchise. - This franchise shall not be interpreted to mean as an exclusive grant of the privileges herein provided for. However, in the event that any competing individual, partnership, or corporation shall receive a similar permit or franchise with terms and/or provisions more favorable than those herein granted or which tend to place the herein grantee at any disadvantage, then such term and/or provision shall be deemed part hereof and shall operate equally in favor of the grantee herein."}},{"id":"PH-H5837-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Sale, Lease, Transfer, Assignment, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise and the rights and privileges acquired thereunder to any person, firm, company, corporation, or legal entity, nor the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity at a time the corporation is not in operation without the prior approval of the Congress of the Philippines.\nAny person or entity to which this franchise is sold, transferred, or assigned shall be subject to all conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5837-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Legislative Amendment. - This franchise is subject to amendment or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5837-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Separability Clause . - If any section or provision of this franchise, as amended, is held or declared unconstitutional or invalid by a competent court in final judgment, the other sections or provisions hereof shall continue to be in force as if the section or provision so annulled or voided had never been incorporated in this franchise."}},{"id":"PH-H5837-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Repealing Clause . - All laws, decrees, orders, instructions, and rules and regulations or parts thereof which are inconsistent herewith are hereby repealed or modified accordingly."}},{"id":"PH-H5837-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Graniting to Silangan Airways, Inc., a Franchise to Establish, Operate and Maintain Transport Services for Carriage of Passengers, Mails, Goods and Property By Air Both Domestic and International","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5838"] = {"id":"PH-H5838","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7350_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"设立Zamboanga市","en":"An Act Declaring October 12 of Every Year a Special Non-working Holiday in the City of Zamboanga","orig":"An Act Declaring October 12 of Every Year a Special Non-working Holiday in the City of Zamboanga"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7350","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7350_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5838-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"October 12 of every year is hereby declared a special non-working holiday in the City of Zamboanga."}},{"id":"PH-H5838-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83"};
  FT["PH-H5839"] = {"id":"PH-H5839","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7351_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Calamba市","en":"An Act Establishing a Rest Park in Barangay Tulo, Municipality of Calamba, Province of Laguna","orig":"An Act Establishing a Rest Park in Barangay Tulo, Municipality of Calamba, Province of Laguna"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 7351","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7351_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5839-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Tourism, a rest park in Barangay Tulo, Municipality of Calamba, Province of Laguna."}},{"id":"PH-H5839-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, through the Philippine Tourism Authority and in coordination with other government agencies concerned, shall prepare the plans necessary for this purpose and effect the construction of the rest park within one (1) year from the approval of this Act."}},{"id":"PH-H5839-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect fifteen (15) days from its complete publication in the Official Gazette or in at least two (2) national newspapers of general circulation, whichever comes earlier."}}],"pack":"ph-p83"};
  FT["PH-H5840"] = {"id":"PH-H5840","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7352_1992.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"将Daet市镇的北甘马粦国立中学改设为北甘马粦州立学院，并入Abano实验小学、Mercedes渔业学校、北甘马粦国立农业学校与北甘马粦国立工艺学校，并为此拨款的法案","en":"An Act Converting the Present Camarines Norte National High School in the Municipality of Daet Into a State College to Be Known as the Camarines Norte State College, Integrating for the Purpose the Abano Pilot Elementary School in Daet, Mercedes School of Fisheries in Mercedes, Camarines Norte National Agricultural School in Labo and the Camarines Norte National School of Arts and Trades in Jose Panganiban, All in the Province of Camarines Norte, and Appropriating Funds Therefor","orig":"An Act Converting the Present Camarines Norte National High School in the Municipality of Daet Into a State College to Be Known as the Camarines Norte State College, Integrating for the Purpose the Abano Pilot Elementary School in Daet, Mercedes School of Fisheries in Mercedes, Camarines Norte National Agricultural School in Labo and the Camarines Norte National School of Arts and Trades in Jose Panganiban, All in the Province of Camarines Norte, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["environment","education","culture"],"docNumber":"Republic Act No. 7352","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7352_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5840-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Camarines Norte National High School is hereby converted into a state college to be known as the Camarines Norte State College and integrating thereto the Abano Pilot Elementary School as its training center; Mercedes School of Fisheries and Camarines Norte National Agricultural School as its College of Agriculture; and the Camarines Norte National School of Arts and Trades as its College of Engineering and Architecture."}},{"id":"PH-H5840-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Camarines Norte State College, which shall hereinafter be referred to as the State College, shall primarily provide higher technological and professional instruction and training in the fields of economics, agriculture, health, engineering, education, management, finance, accounting, forest research and conservation, business and public administration as well as short-term technical and vocational courses. It shall also provide and promote research and extension services, advanced studies and progressive leadership in all areas of discipline and responsibilities."}},{"id":"PH-H5840-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to the two-year agricultural technology curriculum of Camarines Norte National Agricultural School, the State College shall offer undergraduate courses leading to the degree of Bachelor of Science in Agriculture with appropriate major fields of specialization, Bachelor of Science in Agribusiness, Bachelor of Science in Business Administration, Bachelor of Science in Forestry, Bachelor of Arts, Bachelor of Science in Education, Bachelor of Science in Elementary Education, Bachelor of Science in Mining Engineering, Bachelor of Science in Civil Engineering, Bachelor of Science in Architecture, Bachelor of Science in Nursing and graduate courses leading to the degree of Master of Arts in Educational Management, Master of Science in Fisheries, Master of Science in Agriculture, Master in Public Administration, Master in Management, and such other courses as the Board of Regents may deem necessary."}},{"id":"PH-H5840-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The head of the State College shall be known as the President. He shall be appointed by the President of the Philippines upon recommendation of the Board of Regents as hereinafter provided.\nThe powers and duties of the President of the State College, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the president of a state college. His salary shall be fixed by the Board of Regents comparable to that being received by presidents of similar educational institutions of like enrollment and standing.\nThe President of the State College shall hold office for a term of six (6) years without reappointment unless he reaches the age of retirement or earlier removed for cause or incapacitated to discharge the duties of his office."}},{"id":"PH-H5840-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The governing body of the Camarines Norte State Colleges shall be the Board of Regents of the State College. It shall be composed of the following:\nSecretary of Education, Culture and Sports, Chairman;"}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Converting the Present Camarines Norte National High School in the Municipality of Daet Into a State College to Be Known as the Camarines Norte State College, Integrating for the Purpose the Abano Pilot Elementary School in Daet, Mercedes School of Fisheries in Mercedes, Camarines Norte National Agricultural School in Labo and the Camarines Norte National School of Arts and Trades in Jose Panganiban, All in the Province of Camarines Norte, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5841"] = {"id":"PH-H5841","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7353_1992.html","fetchedAt":"2026-10-06","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"设立制度","en":"Rural Act of 1992","orig":"An Act Providing for the Creation, Organization and Operation of Rural Banks, and for Other Purposes \"Rural Act of 1992\""},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7353","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-02","completenessNote":"全文，共 30 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7353_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文条号不连续（自第 1 条起，止于第 32 条，缺 11、21）：经逐条比对原始页面，该处原文没有对应的 “Section N.” 抬头行，系来源页自身的编号跳跃或条文以“续段”形式并入前条，非抽取遗漏，故未擅自补号。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5841-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall be known and cited as the \"Rural Act of 1992.\""}},{"id":"PH-H5841-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The State hereby recognizes the need to promote comprehensive rural development with the end in view of attaining acquitable distribution of opportunities, income and wealth; a sustained increase in the amount of goods and services produced by the nation of the benefit of the people; and in expanding productivity as a key raising the quality of life for all, especially the underprivileged.\nTowards these ends, the State hereby encourages and assists in the establishment of rural banking system designed to make needed credit available and readily accessible in the rural areas on reasonable terms."}},{"id":"PH-H5841-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In furtherance of this policy, the Monetary Board of the Central Bank of the Philippines shall formulate the necessary rules and regulations governing the establishment and operation of rural banks for the purpose of providing adequate credit facilities to farmers and merchants, or to cooperatives of such farmers and merchants and in general, the people of the rural communities, and to supervise the operation of such banks."}},{"id":"PH-H5841-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No rural bank shall be operated without a Certificate of Authority from the Monetary Board of the Central Bank. Rural banks shall be organized in the form of stock corporations. Upon consultation with the rural banks in the area, duly established cooperatives and corporations primarily organize to hold equities in rural banks may organize a rural bank and/or subscribe to the shares of stock of any rural bank: Provided, That a cooperative or corporation owning or controlling the whole or majority of the voting stock of the rural bank shall be subject to special examination and to such rules and regulations as the Monetary Board may prescribe. With exception of shareholdings of corporations organized primarily to hold equities in rural banks as provided for under Section 12-C of Republic Act 337, as amended, and of Filipino-controlled domestic banks, the capital stock of any rural bank shall be fully owned and held directly or indirectly by citizens of the Philippines or corporations, associations or cooperatives qualified under Philippine laws to own and hold such capital stock: Provided, That any provisions of existing laws to own and hold such capital stock: Provided, That any provision of existing laws to the contrary notwithstanding, stockholdings in a rural bank shall be exempt from any ownership ceiling for a period of ten (10) years from the approval of this Act: Provided, further, That any such exemption shall require the approval of the Monetary Board. If subscription of private shareholders to the capital stock of rural cannot be secured or is not available, or insufficient to meet the normal credit needs of the locality, the Land Bank of the Philippines, the Development Bank of the Philippines, or any government-owned or controlled bank or financial institution, on representation of the said private shareholders but subject to the investment guidelines, policies and procedures of the bank or financial institution and upon approval of the Monetary Board of the Central Bank, shall subscribe to the capital stock of such rural bank, which shall be paid in full at the time of subscription, in an amount equal to the fully paid subscribe and unimpaired capital of the private stockholders or such amount as the Monetary Board may prescribed as may be necessary to promote and expand rural economic development: Provided, however, That such shares of stock subscribe by the Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or controlled bank or financial institution may be sold at any time at market value to private individuals who are citizens of the Philippines: Provided, finally, That in the sale of shares of stock subscribed by the Land Bank of the Philippines, the Development bank of the Philippines or any government-owned or controlled bank or financial institution, the registered stockholders shall have the right of preemption within one (1) year from the date of offer in proportion to their respective holdings, but in the absence of such buyer, preference, however, shall be given to residents of the locality or province where the rural bank is located."}},{"id":"PH-H5841-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All members of the Board of Directors of the rural bank shall be citizens of the Philippines at the time of their assumption to office: Provided, however, That nothing in this Act shall be construed as prohibiting any appointive or elective public official from serving as director, officer, consultant or in any capacity in the bank.\nNo Director or officer of any rural bank shall, either directly or indirectly, for himself or as the representative or agent of another borrow any of the deposits or funds of such banks, nor shall he become a guarantor, indorser, or surety for loans from such bank to others, or in any manner be an obligor for money borrowed from the bank or loaned by it except with the written approval of the majority of the directors of the bank, excluding the director concerned. Any such approval shall be entered upon the records of the corporation and a copy of such entry shall be transmitted forthwith to the appropriate supervising department. The director/officer of the bank who violates the provisions of this section shall be immediately dismissed from his office and shall be penalized in accordance with Section 26 of this Act.\nThe Monetary Board may regulate the amount of credit accommodations that may be extended directly to the directors, officers or stockholders of rural banks of banking institutions. However, the outstanding credit accommodations which a rural bank may extend to each of its stockholders owning two percent (2%) or more of the subscribed capital stock, its directors, or officers shall be limited to an amount equivalent to the respective outstanding deposits and book value of the paid-in capital contributions in the bank."}},{"id":"PH-H5841-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Loans or advances extended by rural banks organized and operated under this Act shall be primarily for the purpose of meeting the normal credit needs of farmers, fishermen or farm families owning or cultivating land dedicated to agricultural production as well as the normal credit needs of cooperatives and merchants. In granting of loans, the rural bank shall give preference to the application of farmers and merchant whose cash requirements are small.\nLoans may be granted by rural banks on the security of lands without Torrens Title where the owner of private property can show five (5) years on more peaceful, continuous and uninterrupted possession in concept of owner; or of portions of friar land estates or other lands administered by the Bureau of Lands that are covered by sales contracts and the purchase have paid at least five (5) years installment thereon, without the necessity of prior approval and consent by the Director of lands; or of portions of other estates under the administration of the Department of Agrarian Reform or other government agency which are likewise covered by sales contracts and the purchasers have paid at least five (5) years installment thereon, without the necessity of prior approval and consent of the Department of Agrarian Reform or corresponding government agency; or of homesteads or free patent lands pending the issuance of titles but already approved, are issued, the provisions of any law or regulations to the contrary notwithstanding: Provided, That when the corresponding titles are issued, the same shall be delivered to the Register of Deeds of the province where such lands are situated to the annotation of the encumbrance: Provided, further, That in the case of lands pending homestead of free patent titles, copies of notices for the presentation of the final proof shall also be furnished the creditor rural bank and, if the borrower applicants fail to present the final proof within thirty (30) days from date of notice, the creditor rural bank may do so for them at their expense: Provided, furthermore, That the applicant for homestead or free patent has already made improvements on the land and the loan applied for is to be used for further development of the same or for other productive economic activities: Provided, finally, That the appraisal and verification of the status of a land is a full responsibility of the rural bank and any loan granted on any land which shall be found later to be within the forest zone shall be for the sole account of the rural bank.\nThe foreclosure of mortgage covering loans granted by rural banks and executions of judgment thereon involving real properties levied upon by a sheriff shall be exempt from the publications in newspaper now required by law where the total amount of loan, excluding interest due and unpaid, does not exceed One hundred thousand pesos (P100,000) or such amount as the Monetary Board may prescribe as may be warranted by prevailing economic conditions. It shall be sufficient publication in such cases if the notices of foreclosure and execution of judgment are posted in the most conspicuous area of the municipal building, the municipal public market, the rural bank, the barangay hall, the barangay public market, if any, where the land mortgaged is situated during the period of sixty (60) days immediately preceding the public auction or execution of judgment. Proof of publication as required herein shall be accomplished by an affidavit of the sheriff or officer conducting the foreclosure sale or execution of judgment and shall be attached with the records of the case: Provided, That when a homestead or free patent is foreclosed, the homesteader or free patent holder, as well as his heirs shall have the right to redeem the same within one (1) year from the date of the registration of the foreclosure in the case of land covered by a Torrens Title: Provided, finally, That in any case, borrowers, especially those who are mere tenants, need only to secure their loans with the procedure corresponding to their share.\nA rural bank shall be allowed to foreclose lands mortgaged to it: Provided, That said lands shall be covered under Republic Act No. 6657."}},{"id":"PH-H5841-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"With the view to ensuring the balanced rural economic growth and expansion, rural banks may, within limits and conditions fixed by the Monetary Board, devote a portion of their loanable funds to meeting the normal credit needs of small business enterprises: provided, That loans shall not exceed fifteen percent (15%) of the net worth of a rural bank of such amount as the Monetary Board may prescribe as may be warranted by prevailing economic conditions, and of essential enterprises or industries, other than those which are strictly agricultural in nature."}},{"id":"PH-H5841-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"To provide supplemental capital to any rural bank until it has accumulated enough capital of its own or stimulate private investments in rural banks, the Land Bank of the Philippines or any government-owned or controlled bank or financial institution shall subscribe within thirty (30) days to the capital stock of any rural bank from time to time in an amount equal to the total equity investment of the private shareholders which shall be paid in full at the time of the subscription of such amount as may be necessary to promote and expand rural economic development: Provided, however, That shares of stock issued to the Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or -controlled bank or financial institution, may, pursuant to this section, at any time, be paid off at par and retired in whole or in part if the rural bank has accumulated enough capital strength to permit retirement of such shares; or if an offer is received from private sources to replace the equity investment of the Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or –controlled bank or financial institution with an equivalent investment or more in the equity of such bank. In case of retirement of stock or replacement of equity investment of the Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or –controlled bank or financial institution, the registered private shareholders of the rural bank shall have the right of preemption within one (1) year from the date of offer in proportion to their respective holdings.\nStock held by the Land Bank of the Philippines, the Development Bank of the Philippines or by any government-owned or –controlled bank or financial institution, under the terms of this section, shall be made preferred only as to assets upon liquidation and without power to vote and shall share in dividend distribution from the date of issuance in the amount of four percent (4%) on the first and second years, six percent (6%) on the third and fourth years, eight percent (8%) on the fifth and sixth years, ten percent (10%) on the seventh and eighth years and twelve percent (12%) on the ninth to the fifteen years without preference: Provided, however, That is such stock of the Land Bank of the Philippines, the Development bank of the Philippines or any government-owned or –controlled bank or financial institution is sold to private shareholders, the same may be converted into common stock of the class provide for in Section 10 hereof: Provided, further, That pending the amendment of Articles of Incorporation of the rural bank, if necessary, for the purpose of reflecting the conversion into common stock of preferred stock sold to private stockholders, the transfer shall be recorded by the rural bank in the stock and transfer book and such shareholders shall thereafter enjoy all the rights and privileges of common stockholders. The preferred stocks so transferred shall be surrendered and cancelled and the corresponding common stocks shall be issued.\nThe corporate secretary of the rural bank shall submit to the Central Bank and the Securities and Exchange Commission a report on every transfer of preferred stock to private shareholders, and such report received by the Securities and Exchange Commission shall form part of the corporate records of rural bank. When all the prepared shares of stock of a rural bank have been sold to private shareholders, the Articles of Incorporation of the rural bank shall be amended to reflect the conversion of the preferred shares of stock into common stock. For this purpose, the President, the corporate secretary, and a majority of the Board of Directors, shall be filed with the Securities and Exchange Commission, which shall attach the same to the original Articles of Incorporation on file with said office.\nThe Securities and Exchange Commission shall not register and amended Articles of Incorporation unless accompanied by the Certificate of Authority required under Section 9 of Republic Act No. 337, as amended.\nAll supervised past due and restructured past due loans, including those covered under existing rehabilitation programs of the Central Bank, and fifty percent (50%) of non-supervised past due and restructured past due loans including accrued interest thereon on rural banks organized under Republic Act No. 720, as amended, as of December 31, 1986, shall be converted into preferred stocks, of the rural bank and issued in favor of the Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or –controlled bank or financial institution: Provided, That penalties thereon are hereby warned except accrued interest on arrearages: Provided, further, That rural banks that prefer to settle their arrearages under a plan or payment or a combination of both plan of payment and conversion may do so in accordance with existing regulations and provisions of this Act: Provided, furthermore, That rural banks shall match these preferred stocks with private equity in equal annual installments over a period of fifteen (15) years to begin three (3) years after conversion: Provided, finally, That the Central Bank, the Land Bank of the Philippines, the Development Bank of the Philippines and any government-owned and –controlled bank or financial institution shall continue to rediscount subject to their respective programs, policies and guidelines against papers evidencing a loan granted by a rural bank in order to achieve the declared policy and promote the objectives of this Act."}},{"id":"PH-H5841-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Land Bank of the Philippines, the Development Bank of the Philippines, or any government-owned or –controlled bank or financial institution may obtain from any source as may be authorized under existing laws and regulations such amount as it may require for the purpose of subscribing to the shares of stock of rural bank: as provided in Section 13 of this Act."}},{"id":"PH-H5841-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Stock certificates shall be issued to represent the contributions to capital stock of the rural bank by the Government through the Land Bank of the Philippines, the Development Bank of the Philippines or through any government-owned or –controlled bank or financial institutions, and by qualified persons under such terms and conditions as the Monetary Board mat prescribe. The powers of the Monetary Board over rural banks shall extend to prescribing the amount, value and class of stock issued by any rural bank, organized under this Act.\nSection 11 . The power to supervise the operation of any rural bank by the Monetary Board as herein indicated shall consists in placing limits to the maximum credit allowed to any individual borrower; in prescribing the interest rate; in determining the loan period and loan procedures; in indicating the manner in which technical assistance shall be extended to rural banks; in imposing a uniform accounting system and manner of keeping the accounts and records of rural banks; in instituting periodic surveys of loan and lending procedures, audits, test-check of cash and other transactions of the rural banks; and, in general in supervising the business operations of the rural banks.\nThe Central bank shall have the power to enforce the laws, orders, instructions, rules and regulations promulgated by the Monetary Board applicable to rural banks; to require rural banks, their directors, officers and agents to conduct and manage the affairs of the rural banks in a lawful and orderly manner, and, upon proof that the rural bank of its Board of Directors, or officers are conducting and managing the affairs of the banking in a manner contrary to the laws, orders, instructions, rules and regulations promulgated by the Monetary Board or in a manner substantially prejudicial in the interest of the Government, depositors or creditors, to take over the management of such bank when specifically authorized to do so by the Monetary Board after due hearing process until a new board of directors and officers are elected and qualified without prejudice to the prosecution of the persons for such violations under the provisions of Sections 32, 33 and 34 of Republic Act No. 265, as amended.\nThe management of the rural bank by the Central Bank shall be without expense to the rural bank, except such as is actually necessary for its operation, pending the election and qualification of a new board of directors and officers to take place of those responsible for the violations or acts contrary to the interest of the Government, depositors or creditors.\nThe director and the examiners of the department of the Central Bank charged with the supervision of rural banks are hereby authorized to administer oaths to any director, officer or employee of any rural bank or to any voluntary witness and to compel the presentation of all books, documents, papers or records necessary in his or their judgment to ascertain the facts relative to the true condition of any rural bank or to any loan"}},{"id":"PH-H5841-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"In addition to the operations especially authorized in this Act, any rural bank may:\na. Accept saving and time deposit;\nb. Open current or checking accounts, provided the rural bank has net assets of at least Five million (P5,000,000) subject to such guidelines as may be established by the Monetary Board:\nc. Act as correspondent for other financial institutions;\nd. Act as a collection agent;\ne. Act as official depositary of municipal, city or provincial funds in the municipality, city or province where it is located, subject to such guidelines as may be established by the Monetary Board;\nf. Rediscount paper with the Philippine National Bank, the Land Bank of the Philippines, the Development Bank of the Philippines, or any other banking institution, including its branches and agencies. Said institution shall specify the nature of paper deemed acceptable for rediscount, as well as the rediscount rate to be charged by any of these institutions;\ng. Offer other banking service as provided in Section 72 of Republic Act No. 337, as amended, and\nh. Extend financial assistance to public and private employees in accordance with the provisions of Section 5 of Republic Act No. 3779, as amended.\nWith written permission of the Monetary Board of the Central bank, any rural bank may act as trustee over estates or properties of farmer and merchants.\nNothing in this section shall be construed as precluding a rural bank from performing, with prior approval of the Monetary Board, all the services authorized and mortgage banks, of for commercial banks, under an expanded banking authority as provided in Section 21-B of the same Act."}},{"id":"PH-H5841-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Subject to such guidelines as may be established by the Monetary, rural banks may invest in equities of the allied undertakings are hereinafter enumerated: Provided, That: (a) the total investment in equities shall not exceed twenty- five percent (25%) of the net worth of the rural bank; (b) the equity investment in any single enterprise shall be limited to fifteen percent (15%) of the net worth of the rural bank; and (c) the equity investment of the rural bank in any single enterprise shall remain a minority holding in that enterprise: Provided, further, That equity investment shall not be permitted in non-related activities.\nAllied undertaking shall include:\na. banks, financial institutions and non-bank financial intermediaries;\nb. Warehousing and other post-harvested facilities;\nc. Fertilizer and agricultural chemical and pesticides distribution;\nd. Farm equipment distribution;\ne. Trucking an transportation of agricultural products;\nf. Marketing and agricultural products;\ng. Leasing; and Other undertakings as may be determined by the Monetary Board."}},{"id":"PH-H5841-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Land Bank of the Philippines, the Development Bank of the Philippines or any government-owned or –controlled bank or financial institution shall, within sixty (60) days of certification of the Monetary Board, which shall be final, extend to a rural bank a loan or loans from time to time repayable in ten (10) years, with concessional rates of interest, against security which may be offered by any stockholders or stockholders of the rural bank: Provided:\na. That the Monetary Board is convinced that the resources of the rural bank are inadequate to meet the legitimate credit requirements of the locality wherein the rural bank is established.;\nb. That there is a dearth of private capital in the said locality; and\nc. That it is not possible for the stockholders of the rural bank to increase the paid-up capital thereof."}},{"id":"PH-H5841-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"All rural banks created and organized under the provisions of this Act shall be exempt from the payment of all taxes, fees and charges of whatever nature and description, except the corporate income tax and local taxes, fees and charges, for a period of five (5) years from the date of commencement of operations.\nAll rural banks in operation as of the date of approval of this Act shall be exempt from the payment of all taxes, fees and charges of whatsoever nature and description, except the corporate income tax and local taxes, fees and charges, for a period of five (5) years from the approval of this Act."}},{"id":"PH-H5841-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"In an emergency or when a financial crisis is imminent, the Central Bank may give a loan to any rural bank against assets of the rural bank which may be considered acceptable by a concurrent vote of at least four (4) members of the Monetary Board.\nIn normal times the Central bank may rediscount against paper evidencing a loan granted by a rural bank to any of its customers which can be liquefied for a period of three hundred sixty (360) days: Provided, however, That for the purpose of implementing a nationwide program of agricultural and industrial development, rural banks are hereby authorized, under such terms and conditions as the Central bank shall prescribe, to borrow, on a medium – or long-term basis, funds that the Central Bank or any other government financing institution shall borrow from the Development Bank of the Philippines or other international or foreign-lending institutions for the specific purpose of financing the abovestated agricultural and industrial program. Repayment of loans obtained by the Central Bank of the Philippines or any other government financing institutions from said foreign-lending institutions under this section shall be guaranteed by the Republic of the Philippines."}},{"id":"PH-H5841-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Deposits of rural banks with government-owned or –controlled financial institutions like the Land Bank of the Philippines, the Development Bank of the Philippines, and the Philippine national Bank are exempted from the Single Borrower’s Limit imposed by the General Banking Act.\nIn areas where there are no government banks, rural banks may deposit in private banks more than the amount prescribed by the Single Borrower’s Limit subject to Monetary Board regulations."}},{"id":"PH-H5841-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"To encourage consolidation and mergers of rural banks, if there are five (5) or more rural banks within the region that merge and consolidate within three (3) years from the enactment of this Act, the merged or consolidated entity will be given the following incentives for a period of seven (7) years:\na. Its deposit liabilities shall be subjected to only one-third (1/3) of reserves normally required for rural banks;\nb. Its reserve requirement can all be maintained under interest-bearing government securities but kept unencumbered with government financial institutions or the Central Bank; and\nc. It shall have unrestricted branching right within the region, free from any assessment or surcharge required in setting up a branch but under coordination with the Central bank which will have to assess that there are qualified personnel, control and procedures to operate the branch."}},{"id":"PH-H5841-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The Central Bank of the Philippines shall extend technical assistance to any rural bank in the process of organization or during the course of operations whenever it is requested to do so or whenever the Monetary Board deems it necessary to preserve, protect and promote the objectives of this Act: Provided, however, That said assistance shall be without cost or obligation on the part of the rural bank."}},{"id":"PH-H5841-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Any city or municipal trial court in his capacity as notary public ex officio shall administer the oath to or acknowledgement the instruments of any rural bank and to borrowers or mortgagors, fee from all charges, fees and documentary stamp tax, collectible under existing laws, relative to any loan or transaction not exceeding Fifty thousand pesos (P50,000), or such amount as the Secretary of Finance, upon recommendation of the Monetary Board may prescribe as may be necessary to promote and expand the rural economy.\nSection 21 . Any Register of Deeds shall accept from any rural bank and its borrowers and mortgagors for registration, free from all charges, fees and documentary stamp tax, collectible under existing laws, any instrument, whether voluntary or involuntary, relating to loans or transaction extended by a rural bank in an amount not exceeding Fifty thousand pesos (P50,000): Provided, however, That charges, if any, shall be collectible on the amount in excess of Fifty thousand pesos (P50,000); and that in instruments related to assignments of several mortgage consolidated in a single deed, if any, shall be levied only on the amount in excess of Fifty thousand pesos (P50,000) of the consideration in the assignments of each mortgage, of such amount as the Secretary of Finance, upon recommendation of the Monetary Board may prescribe as may be necessary to promote and expand the rural economy."}},{"id":"PH-H5841-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Any rural bank organized under this Act may, pursuant to regulations promulgated for the purpose by the Monetary Board, be required to contribute to the Central Bank an annual fee to help defray the cost of maintaining the appropriate supervising department within the central bank in an amount to be determined by the Monetary Board but in no case to exceed one-fortieth of one percent (1/40 of 1%) of its average total assets during the preceding year, as shown on its end-of-month balance sheets, after deducting its cash on hand and amounts due from banks, including the Central Bank."}},{"id":"PH-H5841-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Every individual acting as officer or employee of a rural bank and handling funds or securities amounting to Five thousand pesos (P5,000) or more than one (1) year, shall be covered by an adequate bond as determined by the Monetary Board; and the bylaws of the rural bank may also provide for the bonding of other employees or officers of rural banks."}},{"id":"PH-H5841-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"For the purpose of carrying out the objectives of this Act, the Central Bank is authorized to require the services and facilities of any department or instrumentality of the Government or any officer or employee of any such department or government instrumentality."}},{"id":"PH-H5841-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Rural banks organized and operated under the provisions of this Act shall act as agents of the Philippine National Bank, the Land Bank of the Philippines and the Development Bank of the Philippines in places where these banks have no offices, subject to accreditation guidelines."}},{"id":"PH-H5841-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Without prejudice to any prosecution under any law which may have been violated a fine of not more than ten thousand pesos (P10,000) or imprisonment of not less than six (6) months but not more than ten (10) years, or both, at the discretion of the court, shall imposed upon:\na. Any officer, employee, or agent of a rural bank who shall:\n1. Make fake entries in any bank report or statement thereby affecting the financial interest of or causing damage to, the bank or any person;\n2. Without order of a court of competent jurisdiction, disclose any information relative to the funds or properties in the custody of the bank belonging to private individuals, corporations, or any other entity;\n3. Accept gifts, fees or commission or any other form of remuneration in connection with the approval of a loan from said bank; or\n4. Overvalue or aid in overvaluing any security for the purpose of influencing in any way the action of the bank on any loan; or\n5. Appear and sign as guarantor, indorser, or surety for loans granted; or\n6. Violate any of the provisions of this Act.\nb. Any applicant for a loan from, or borrower of a rural bank who shall:\n1. Misuse, misapply, or divert the proceeds of the loan obtained by him from its declared purpose; or\n2. Fraudulently overvalue property offered as security for loan from said bank; or\n3. Give out or furnish false misrepresentation of material facts for the purpose of obtaining, renewing, or increasing a loan or extending the period thereof; or\n4. Attempt to defraud the said bank in the event of court action to recover a loan; or\n5. Offer any officer, employee, or agent of a rural bank as a gift, fee, commission, or other form of compensation in order to influence such bank personality in approving an application; or\n6. Dispose or encumber the property or the crops offered as security for the loan.\nc. Any examiner, or officer or employee of the Central Bank of the Philippines or other department, bureau, office, branch or agency of the Government who is assigned to examine, supervise, assist or render technical services to rural banks and who shall connive or aid in the commission of the same."}},{"id":"PH-H5841-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Any municipal trial court judge or register of deeds who shall demand or accept, directly or indirectly, any gift, fee, commission or other form of compensation in connection with the service, or the registration of documents required to be as provided in Section 20 and by said register of deeds as proposed in Section 21 of this Act, shall be punished by One thousand pesos (P1,000) or by imprisonment for not more than one (1) year, or both, at the discretion of the court."}},{"id":"PH-H5841-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Any bank not organized under this Act and any person, association, or corporation doing the business of banking, not authorized under this Act which shall use the words \"Rural Bank\" as part of the name or title of such bank or of such person, association, or corporations, shall be punished by a fine of not less than Fifty pesos (P50) for each day during which said words are so used."}},{"id":"PH-H5841-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"The Monetary Board of the Central Bank shall submit a report to the Congress of the Philippines as the end of each calendar year of all the rules and regulations promulgated by it in accordance with the provisions of this Act, as well as its other actuations in connection with rural banks, together with an explanation of its reasons therefor."}},{"id":"PH-H5841-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"If any provision or section of this Act or the application thereof to any person or circumstances is held invalid, the other provisions or sections of this Act, and the application of such provision or section to other persons or circumstances, shall not be affected thereby."}},{"id":"PH-H5841-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Republic Act No. _____, as amended, is hereby repealed. The provisions of Republic Act No. 265, as amended, and Republic Act No. 337, as amended, insofar as they are applicable and not in conflict with any provision of this Act, are hereby made a part of this Act."}},{"id":"PH-H5841-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83"};
  FT["PH-H5842"] = {"id":"PH-H5842","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7354_1992.html","fetchedAt":"2026-10-06","articleCount":36,"structureMode":"ARTICLE","title":{"zh":"关于设立菲律宾邮政公司并界定其权力、职能与责任、规定行业监管的法案","en":"An Act Creating the Philippine Postal Corporation, Defining Its Powers, Functions and Responsibilities, Providing for Regulation of the Industry and for Other Purposes Connected Therewith","orig":"An Act Creating the Philippine Postal Corporation, Defining Its Powers, Functions and Responsibilities, Providing for Regulation of the Industry and for Other Purposes Connected Therewith"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7354","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-03","completenessNote":"全文，共 36 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7354_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5842-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Postal Service Act of 1992.-"}},{"id":"PH-H5842-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Definitions. - As used in this Act:\na. \"Corporation\" shall refer to the Philippine Postal Corporation as provided for in this Act.\nb. \"Letter\" shall refer to a message in writing, which maybe in any language or in code, contained in a sealed or unsealed envelope or not in an envelope at all, of such physical dimensions and weights allowed by the Corporation or the Government, and intended for delivery to a person or entity displayed legibly on one of its faces.\nc. \"Mail\" or \"mail matters\" shall refer to all matters authorized by the Government to be delivered through the postal service and shall include letters, parcels, printed materials, and money orders.\nd. \"Obligations\" refer to all financial liabilities of the Corporation which are evidenced by promissory notes, bonds, debentures, mortgages or any other form of indebtedness.\ne. \"Parcel\" means a rectangular box, the dimension and weight of which is as specified by the Corporation or the Government containing goods or some form of transportable property intended for delivery to an addressee prominently displayed on at least one (1) of its sides.\nf. \"Printed matter\" means the reproduction upon paper, by any process except that of handwriting or typewriting, of any words, letters, characters, figures or images, or any combination thereof, not having the character of an actual and personal correspondence."}},{"id":"PH-H5842-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Policy and Objectives. - The delivery of letters, parcels and other mail matters is a basic and strategic public utility which the State shall provide, directly or indirectly through, and/or with other duly authorized entities or persons. Accordingly, the collection, sorting, storage, transporting, and delivery thereof shall be done with utmost dispatch in the most economical, reliable and secure manner that available technology will permit.\nThe State shall pursue the following objectives of a nationwide postal system:\na. to enable the economical and speedy transfer of mail and other postal matters, from sender to addressee, with full recognition of their privacy or confidentiality;\nb. to promote international interchange, cooperation and understanding through the unhampered flow or exchange of postal matters between nations;\nc. to cause or effect a wide range of postal services to cater to different users and changing needs, including but not limited to, philately, transfer of monies and valuables, and the like;\nd. to ensure that sufficient revenues are generated by and within the industry to finance the overall cost of providing the varied range of postal delivery an messengerial services as well the expansion and continuous upgrading of service standards by the same.\nARTICLE II\nCREATION, POWERS AND RESPONSIBILITIES OF THE PHILIPPINE POSTAL CORPORATION"}},{"id":"PH-H5842-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Creation. - There is hereby created a corporate body to be known as the Philippine Postal Corporation, hereafter referred to as the Corporation, which shall be attached to the Department of Transportation and Communications for purposes of policy coordination."}},{"id":"PH-H5842-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Responsibilities and Functions. - The Corporation shall have the following functions and responsibilities:\na. to provide for the collection, handling, transportation, delivery, forwarding, returning and holding of mails, parcels, and like materials throughout the Philippines and, pursuant to agreements entered into, to and from foreign countries;\nb. to determine and dispose of, in a manner it deems most advantageous, with law and settled jurisprudence, confiscated or non-available mail matters, prohibited articles, dead letters and undelivered mails, except the sale of prohibited drugs, dangerous materials, and other banned articles as defined by law;\nc. to plan, develop, promote, and operate a nationwide postal system with a network that extends or makes available, at least ordinary mail service, to any settlements in the country."}},{"id":"PH-H5842-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Powers. - To achieve its objectives and undertake its functions effectively, the Corporation shall have the following powers:\na. to charge fees for postal services to be rendered, receipt the same, and prescribe, the manner it is to be paid and collected, subject to the provisions of this Act;\nb. to establish and maintain post offices, postal stations, collection points and related facilities and equipment of such character and in such locations that postal users throughout the Philippines will, consistent with reasonable economies of operations, have ready access to essential postal services;\nc. to issue and sell postage stamps and other stamped paper, cards, and envelopes as it may deem necessary or desirable;\nd. to issue money orders or checks for transmittal through the mails and authorize the issuance of a replacement in cases of lost, stolen, stale, or destroyed money order or check;\ne. to offer a wide array of postal services other than ordinary mail and parcels, which however, shall not be compulsory, discriminatory nor unfairly competing with similar private enterprises, such as money order, parcel, postal savings bank, philatelic, and other types of services which are internationally accepted as part of postal business;\nf. to adopt and promulgate such rules and regulations as would improve the postal system or implement the provisions of this Act."}},{"id":"PH-H5842-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Corporate Powers. - The Corporation shall have all corporate powers defined under the Corporation Code, such as, but not limited to the following:\na. to sue and be sued in its official name;\nb. to enter into and perform contracts, execute instruments, and determine the character of, and necessity for, its expenditures;\nc. to determine and keep its own system of accounts following generally accepted principles of accounting, as well as the forms and contents of its contracts and other business documents;\nd. to acquire, in any lawful manner, such personal or real property; or any interest therein, as it deems necessary or convenient in the transaction of its business; to hold, maintain, sell, lease, or otherwise dispose of such property or any interest therein; and to provide services in connection therewith and charges therefor;\ne. to construct, operate, lease, and maintain buildings, facilities, equipment, and other improvements on any property owned, controlled or leased by it;\nf. to accept gifts, donations, bequests, services, or properties, real or personal, as it deems necessary or convenient in the transaction of its business;\ng. to settle, under such terms and conditions on amounts most advantageous to it, any claim by or against it;\nh. to adopt and use a corporate seal;\ni. to exercise all other corporate powers incidental, necessary, or appropriate to its postal business."}},{"id":"PH-H5842-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Board of Directors. - The powers of the Corporation shall be vested in and exercised by a Board of Directors of seven (7) members to be elected by the shareholders of record at the annual business meeting of the Corporation. Initially and to organize the Corporation, the President shall appoint all the members, with the Postmaster General as one of the members to represent the government shareholdings. When the private shareholdings become sufficient to elect at least one (1) Director, the appointment or election of directors shall be done in accordance with the Corporation Law with the Secretary of Transportation and Communications exercising the right to vote the government shares of stocks. The Board shall elect a chairman from among its members.\nThe members of the Board so appointed by the President shall hold office for a term of five (5) years each, except of those first appointed, two (2) members shall have a term of five (5) years, two (2) with three (3) years, and two (2) with one (1) year. Thereafter, the appointment shall be in accordance with the Corporation Law.\nThe Board shall meet regularly once a month and may hold special meetings to consider urgent matters upon call of the Chairman or any three (3) members. A majority shall constitute a quorum to transact business, and the vote of at least a majority of the members present at a meeting at which there is a quorum be valid as a corporate act.\nThe members of the Board, except the Postmaster General or his alternate, shall receive for every meeting actually attended a per diem not exceeding the lowest monthly pay of a regular postal employee, but in no case will the total amount received in any one (1) month by each member exceed four times (4x) the per diem per meeting. Members of the Board shall be reimbursed by the Corporation for actual expense, including travelling and subsistence expenses, incurred by them in the performance of their duties.\nNo member of the Board shall have financial, or pecuniary interest, directly or indirectly, in any business contract or transaction entered into by the Corporation or in any privilege granted by it. Neither shall a member have any interest, financial or otherwise in any undertaking or business with an inherent conflict of interest with the Corporation.\nARTICLE III\nCAPITAL AND FISCAL ADMINISTRATION"}},{"id":"PH-H5842-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Capitalization. - The Corporation shall have an authorized capital stocks of Ten billion pesos (P10,000,000,000.00) divided into forty-five(45) million Class \"A\" shares and fifty-five (55) million Class \"B\" shares, each voting and with a par value of One hundred pesos (P100.00). The Class \"A\" shares shall be fully subscribed by the Government or any of its instrumentalities, and may only be owned, sold to, bought or held by a government entity. The Class \"B\" shares may be owned by private entities and sold through tenders, public offerings, or the stock market, at such time, price or numbers as may be authorized by the Board in accordance with the Corporation Law.\nThe subscriptions of the National Government in Class \"A\" shares shall be paid as follows:\na. the unexpended balances of appropriations in the current General Appropriations Act, Executive Order No. 182 and other acts in force upon approval hereof, pertaining to, held or used by, or available to the former Bureau of Posts, and its successor Postal Services Office, of the Department of Transportation and Communications;\nb. the values of all the existing assets of the Bureau of Posts and its successor office the Postal Services Office, and the various postal facilities throughout the country owned by it, to be determined by an independent appraiser within a year of the effectivity of this Act;\nc. any surplus income that may be derived from or accrued to the Corporation upon its organization into a corporate body and its assumption of the assets and liabilities of the Postal Services Office; and\nd. such amount as may be appropriated from time to time from the funds of the National Treasury not otherwise appropriated, including any outlay from the Infrastructure Program of the National Government."}},{"id":"PH-H5842-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Source of Funds. - The following shall constitute the sources of funds against which the operating expenses of the Corporation may be drawn:\na. all revenues from postal and allied services operated or rendered by the Corporation, including remittances from foreign postal administrations;\nb. proceeds of grants, donations, disposal of assets and sale of non-mailable or confiscated mail matters, loans and other form of indebtedness enter into by the Corporation,\nc. interest which may be earned on investments or on idle cash of the Corporation;\nd. drawings upon the capital or surplus of the Corporation."}},{"id":"PH-H5842-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Management of Funds. - The Corporation may, from time to time, invest any of its funds not immediately required to be expended in meeting its obligations or in the discharge of its functions, in such secured notes, government securities, and other negotiable instruments that satisfy the guidelines prescribed by the Board.\nAll funds of the Corporation shall be deposited in such commercial and universal banks as may be accredited by the National Treasurer as depository of government funds. The Board shall designate the official signatories of the Corporation with regards to the deposit or withdrawal of the Corporation's monies in such banks."}},{"id":"PH-H5842-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Obligations. - The Corporation is authorized to secure or contract domestic or foreign loans, credits and other indebtedness, and to issue bonds, notes, debentures, securities and other instruments of indebtedness as it may deem necessary to carry out the purposes of this Act, provided that:\na. the outstanding liabilities and obligations, foreign and domestic, shall not exceed, at any time, fifty percent (50%) of its net worth;\nb. the foreign indebtedness can only be contracted with the concurrence of the Department of Finance, or under such terms and conditions established by the Central Bank;\nc. the annual amortizations on principal and interest shall not be more than twenty percent (20%) of the prior year's gross revenues;\nd. where appropriate, obligations incurred from private sources of capital may be secured by suitable assets or backed by priority claims against property of the Corporation;\ne. obligations shall be considered the sole liability of the Corporation, unless otherwise guaranteed by the Republic of the Philippines through the Secretary of Finance.\nf. issuance of bonds or long term notes shall be with prior approval of or in accordance with the rules issued by the National Treasurer."}},{"id":"PH-H5842-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Annual Budget. - The Corporation shall, every year, prepare and adopt estimates of income and expenditures and capital budget of the Corporation for the ensuing year. Unless the Corporation shall require subsidy and/or a guarantee of its liability form the National Treasury, its budget for the year need not be submitted to Congress for approval and inclusion in the General Appropriations Act.\nSupplementary estimates may be prepared and adopted at any of the Board meeting called for that purpose."}},{"id":"PH-H5842-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Exemption from Taxes, Customs and Tariff Duties . - The importation of equipment, machineries, spare parts, accessories, and other materials, including supplies and services used directly in the operations of the Postal System, not obtainable locally on favorable terms, shall be exempt from all direct and indirect taxes, customs duties, fees, imports, tariff duties, compensating taxes, wharfage fees and other charges and restrictions, the provisions of existing laws to the contrary notwithstanding.\nAll obligations entered into by the Corporation and any income derived therefrom, including those contracted with private international banking and financial institutions, shall be exempt from all taxes on both principal and interest.\nThe Corporation is also exempt from the payment of capital gains tax, local government imposts and fees after December 31, 1997: Provided, That it may offset the full value of capital investments not otherwise funded by the National Government against any income tax due for the same period."}},{"id":"PH-H5842-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Annual Accounts. - The Corporation shall maintain such accounts and other records under a commercial system of accounting on a calendar year basis. The Board shall cause the publication of the Corporation's annual statement of income and expenditures, including its balance sheet at the end of the reporting period.\nThe audited annual statement of accounts of the Corporation shall present a true and fair value of the financial position of the Corporation and of the results of the operations during the year to which it relates.\nFor completeness of postal statistics, the Corporation shall likewise record the quantity of official business mails, and the equivalent revenues foregone had the corresponding postage been collected thereto. This shall include \"franked mail\", or mail matter transmitted without payment of postage under the autographic or facsimile signature of officials to whom this privilege is extended by law, and under such rules promulgated by the Corporation to prevent the unauthorized use thereof."}},{"id":"PH-H5842-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Auditor. - In consonance with existing laws and regulations, the Commission on Audit shall appoint and assign such personnel as may be necessary to audit the accounts of the Corporation. However, the Board may engage the services of any person or firm duly authorized by law for the audit of accounts of the Corporation for purposes of complying with its international contractual commitments or with the requirements of holders of Class \"B\" shares.\nThe Board shall determine the remuneration, compensation or reimbursement of expenses that may be reasonable and appropriate under the circumstances for either or both of the internal and external Auditors mentioned above."}},{"id":"PH-H5842-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Auditor's Report. - The Auditor shall as soon as practicable, but not later than three (3) months after the accounts have been submitted for audit, send an annual report to the Board. The Auditor may also submit such periodical or special reports to the Board as may be appear to him necessary, or as requested by the Board."}},{"id":"PH-H5842-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Annual Report. - The Board shall submit to the appropriate regulatory agencies, as identified in Article V of this Act, and to both Houses of Congress, together with the Auditor's Report on the relevant accounts, annual report generally dealing with the activities and operations of the Corporation during the preceding year, and containing such other information as may be relevant in assessing its overall corporate performance, particularly statistics about the mails, parcels, and mail matters handled or processed by it, and indicators of productivity relating output with the resources used.\nARTICLE IV\nMANAGEMENT AND PERSONNEL"}},{"id":"PH-H5842-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Delegation of Authority. - Except for those powers, functions, or duties specifically vested in the Board, the Board may delegate the authority vested in it to the Postmaster General under such terms, conditions and limitations as it may prescribe. The Board may establish committees, with such authority as the Board determines appropriate to carry out its functions and duties. Any power delegated herein shall not relieve the Board of full responsibility for the performance of its duties and functions, and shall be revocable by the Board in its exclusive judgment."}},{"id":"PH-H5842-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Executive Officers. - The Corporation shall be managed by a Postmaster General who shall be assisted by as many Assistant Postmasters General as the Board may deem necessary for postal efficiency. They shall be natural-born citizens of the Philippines, at least thirty five (35) years old, holders of a college degree, of good moral character and proven executive ability and competence. Initially and until such time that issued Class \"A\" shares do not fall below sixty percent (60%) of the total voting stocks, the Postmaster General shall be appointed by the President; thereafter, the appointment shall be in accordance with the Corporation Law. At least a majority of the Assistant Postmasters General must be career postal officials who shall be appointed, and may be removed for cause by the Board, upon recommendation of the Postmaster General.\nThe yearly total monetary compensation, including salary, bonuses and allowances of the Postmaster General and each Assistant Postmaster General, shall be set by the Board: Provided, That, in the case of the Postmaster General, it shall not exceed twenty times (20x) the lowest annual salary of a regular employee of the Corporation; and in the case of the Assistant Postmaster General, his annual total monetary compensation shall not exceed eighteen times (18x) the lowest annual salary of a regular postal employee in the Corporation."}},{"id":"PH-H5842-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Powers and Functions of the Postmasters General. - As the Chief Executive Officer, the Postmaster General shall have the following powers and functions:\na. to represent the Corporation in all dealings with other offices, agencies, and instrumentalities of the Government and with all other persons and entities, whether public or private, domestic, foreign or international;\nb. to sign for and on behalf of the Corporation contracts and debt instruments authorized and approved by the Board;\nc. subject to the approval of the Board, to determine the staffing pattern and the number of personnel, define their duties and responsibilities, and fix their salaries emoluments in accordance with the approved compensation structure of the Corporation;\nd. to appoint, promote, assign, reassign, transfer and remove personnel below the ranks of Assistant Postmaster General; Provided, That in the case of removal of officials and employees, the same may be appealed to the Board;\ne. to delegate any of his powers, duties or functions to any official of the Corporation, subject to the approval of the Board;\nf. to perform such other functions and duties as the Board may direct."}},{"id":"PH-H5842-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Merit System. - The Corporation shall establish a human resources management system which shall govern the selection, hiring, appointment, transfer, promotion, or dismissal of all personnel. Such system shall aim to establish professionalism and excellence at all levels of the postal organization in accordance with sound principles of management.\nA progressive compensation structure, which shall be based on job evaluation studies and wage surveys and subject to the Board's approval, shall be instituted as an integral component of the Corporation's human resources development program. The Corporation, however, may grant across the board salary increase or modify its compensation structure as to result in higher salaries, subject to either of the following conditions:\na. there are evidences of prior improvement in employee productivity, measured by such quantitative indicators as mail volume per employee and delivery times.\nb. a law raising the minimum wage has been enacted with application to all government employees or has the effect of classifying some positions in the postal service as below the floor wage."}},{"id":"PH-H5842-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Applicability of Civil Service Law. - All permanent officers and employees of the Corporation below the rank of Assistant Postmaster General shall be subject to the Civil Service Law, rules and regulations so long as the Corporation is majority-owned by the Government. The hiring of temporary workers or casuals to meet peak or seasonal volume of mail matters shall be exempt from the provision of this Section."}},{"id":"PH-H5842-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Prohibition of Strikes, Work Stoppages and Slowdowns. - In view of the vital nature of postal services and its effect on national interests, the officers and employees of the Corporation are prohibited from conducting strikes, work slowdowns or stoppages, and such other acts that may disrupt the timely delivery of mail matters.\nNothing in this provision shall prevent such officers and employees from forming a union or employee association in accordance with Civil Service rules and regulations and for the purpose of securing changes or improvements in the terms and conditions of their employment."}},{"id":"PH-H5842-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Exemption from Rules and Regulations of the Compensation and Position Classification Office. - All personnel and positions of the Corporation shall be governed by Section 22 hereof, and as such shall be exempt from the coverage of the rules and regulations of the Compensation and Position Classification Office. The Corporation, however, shall see to it that its own system conforms as closely as possible with that provided for under Republic Act No. 6758.\nARTICLE V\nREGULATIONS OF THE POSTAL DELIVERY SERVICES INDUSTRY"}},{"id":"PH-H5842-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"The Regulatory Authority. - The exclusive power and authority to regulate the postal delivery services industry or those engaged in domestic postal commerce, as provided for under Presidential Decree No. 240, shall be vested with the Department of Transportation and Communications (DOTC), and may be delegated by the DOTC Secretary to the National Telecommunications Commission. The regulatory authority shall have the responsibility of investigating and prosecuting postal offenses of postal service establishments, whether civil or criminal, and of instituting necessary action or proceedings. Nothing in this Section shall prevent or limit the Corporation's authority to investigate, prosecute or penalize offenses committed by its employees."}},{"id":"PH-H5842-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Registration of the Postal Service Establishments. - The regulatory authority shall:\na. register and prequalify any person, natural or juridical, other than freight forwarders, who engaged in the business of letter and parcel messengerial services, door-to-door delivery, or the transporting of the property of others that are similar to mail or parcel.\nb. upon petition and public hearing, approve the rate to be charged by the Corporation for ordinary mail."}},{"id":"PH-H5842-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Postal Offenses. - The Regulatory Authority shall exercise the following powers if, in its judgment, postal laws have been, are being, or about to be violated:\na. to conduct, directly or with the Corporation, and with the assistance of law enforcers, searches of any vehicle, vessel or aircraft for stolen mail matter or any mail matter being transported in violation of law, whenever there is reasonable ground to believe that such prohibited mail matter is contained therein;\nb. to issue search warrants, under the same conditions prescribed for judicial officers, authorizing the search of any place not used as a dwelling, for any stolen mail matter;\nc. with the help of law enforcers, and through his duly authorized representatives, to make arrest and seizure for violation of any postal law;\nd. to offer and pay rewards for information and services in connection with violations of the postal laws.\nARTICLE VI\nTRANSITORY PROVISIONS"}},{"id":"PH-H5842-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Abolition of the Postal Services Office. - The Postal Services Office under the Department of Transportation and Communications, is hereby abolished. All powers and duties, rights and choses of actions, vested by law or exercise by the Postal Services Office and its predecessor Bureau of Posts, are hereby transferred to the Corporation.\nAll real and personal properties which upon the effectivity of this Act are vested in, or owned by, the Postal Services Office are transferred to the Corporation without need of conveyance, transfer or assignment. Likewise, all funds, revenues and properties owned by the defunct Postal Savings Bank, which are now administered by the Philippine National Bank, are transferred to the Corporation, provisions of Presidential Decree No. 241 notwithstanding. The Philippine National Bank is hereby directed to transfer and turn over to the Corporation all funds, revenues, and properties of the defunct Postal Savings Bank administered by it, after deducting any liability connected with such assets.\nAll contracts, records, and documents relating to the operation of the Postal Services office and its postal field offices are hereby transferred to the corporation.\nTo ensure smooth transition into a corporate structure, the incumbent Assistant Secretary for Postal Services shall continue to hold office and assume the powers and functions of the Postmaster General under Section 21 hereof until his successor shall have been duly appointed and inducted into office. Officials and employees of the Postal Services Office shall be absorbed into the Corporation on the basis of merit and fitness: Provided, That officers and employees who shall be laid off during the first two (2) years of the effectivity of this Act and as a result of the organization of the Corporation, shall be entitled to gratuity at the rate equivalent to one and one-fourth (1 1/4) month's salary for every year of continued and satisfactory service rendered or the equivalent nearest fraction thereof favorable to them on the basis of the highest salary received, in addition to the retirement benefits or pensions under existing retirement law. Retirement gratuities of officials and employees who shall not be retained by the Corporation shall be for the account of and reimbursed by the National Government.\nAny of such officers and employees who may later be reinstated in the Corporation, or who is rehired in any government office or instrumentality, shall refund the unearned portion of gratuity received from the Corporation before he shall be reinstated or rehired."}},{"id":"PH-H5842-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Appropriations. - To provide for any extraordinary expenses of the Corporation upon its organization, unavailed portion of the excess of actual operating income over the estimated expenses of the Postal Service Office, if any, at the time of the passage of this Act is hereby appropriated for purposes that the Board may approve. This shall be considered as part of the paid-up capital under paragraph (c) of Section 9 hereof.\nFor the purpose of funding the gratuity mentioned in Section 29 hereof, the amount of Three hundred million pesos (P300,000,000.00), inclusive of the amount referred to above, is hereby appropriated out of any funds available and not otherwise appropriated in the National Treasury."}},{"id":"PH-H5842-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Savings Clause. - All orders, determinations, rules, regulations, permits, certificates, licenses and privileges which have been issued, made, granted or allowed to become effective by the former Postal Services Office or its predecessors, shall continue to be in effect according to their terms until modified, terminated, superseded, set aside, or repealed.\nNo suit, action or other proceeding commenced by or against any officer in his official capacity as an officer of any division or agency of the former Postal Services Office (Bureau of Posts), the functions of which are transferred by this Act to the Corporation, shall abate by reason of this act. In like manner, no cause of action by or against such division or agency or by against any officer thereof in his official capacity shall abate by reason of the enactment of this Act. Causes of actions, suits or other proceedings may be asserted by or against the Corporation of such official of the Corporation as may be appropriate.\nARTICLE VII\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H5842-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Relationships with other Institutions. -\na. In the event the Corporation decides to reactivate or reopen the Postal Savings Bank after ascertaining its financial viability and in response to public clamor, it shall operate such services without, as much as practicable, unduly competing with rural, commercial, or universal banks. The Corporation shall utilize the facilities of such banks whenever convenient and economical, under such terms and conditions as may be agreed between the parties concerned.\nb. The Corporation shall establish a working arrangement with the Bureau of Customs to facilitate the inspection, release or delivery of foreign parcels and mail matters which may be liable for customs taxes and other import charges. It may organize a special unit or designate specific postal branches for handling such mail matters. In lieu of assigning its own personnel, the Bureau of Customs may appoint the Corporation or delegate its customs and collection powers thereto, subject to some mutually agreed upon terms and conditions, including the reimbursements of cost to the Corporation or the payment for services based on percentage of the amount of tax collected.\nc. Any local government unit may enter into contract with the Corporation for the use of the former's building, facilities, or land, either gratis or for a consideration, or for the management and operation by the local government unit of a post office or postal branch in its territory."}},{"id":"PH-H5842-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Limited Liability. - Unless otherwise declared and mutually agreed upon at the time of posting, the liability of the Corporation with respect to its contractual obligations to delivery mail matters shall be limited to that amounts or values provided for by the Universal Postal Union and by international or bilateral agreements to which the Philippines is a signatory."}},{"id":"PH-H5842-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Separability Clause . - If for any reason, any section or provision of this Act is declared to be unconstitutional or invalid, the other sections or provisions hereof, which are not affected thereby, shall continue in full force and effect."}},{"id":"PH-H5842-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Repealing Clause . - All acts, decrees, orders, executive orders, instructions, rules and regulations or parts thereof inconsistent with the provisions of this Act are repealed or modified accordingly.\nAll franking privileges authorized by law are hereby repealed, except those provided for under Commonwealth Act No. 265, Republic Acts Numbered 69, 180, 1414, 2087 and 5059. The Corporation may continue the franking privilege under Circular No. 35 dated October 24, 1977 and that of the Vice President, under such arrangements and conditions as may obviate abuse or unauthorized use thereof."}},{"id":"PH-H5842-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Effectivity . - This Act shall take effect thirty (30) days after its approval and publication in the Official Gazette."}}],"pack":"ph-p83","titleTranslation":{"engine":"manual-llm","reviewed":false,"source":"An Act Creating the Philippine Postal Corporation, Defining Its Powers, Functions and Responsibilities, Providing for Regulation of the Industry and for Other Purposes Connected Therewith","note":"人工逐条翻译（模型产出，未经人工复核）；公司名、地名、机构名保留原文。"}};
  FT["PH-H5843"] = {"id":"PH-H5843","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7355_1992.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":"规定承认国家活态瑰宝并促进和发展传统民间艺术、为此提供资金并为相关目的法案","en":"An Act Providing for the Recognition of National Living Treasures, Otherwise Known as the Manlilikha Ng Bayan, and the Promotion and Development of Traditional Folk Arts, Providing Funds Therefor, and for Purposes`","orig":"An Act Providing for the Recognition of National Living Treasures, Otherwise Known as the Manlilikha Ng Bayan, and the Promotion and Development of Traditional Folk Arts, Providing Funds Therefor, and for Purposes`"},"level":"law","status":"active","topics":["culture"],"docNumber":"Republic Act No. 7355","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-03","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7355_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5843-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the Manlilikha ng Bayan Act."}},{"id":"PH-H5843-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Policy and Objectives. - It is hereby declared to be the policy of the State to preserve and promote its traditional folk arts whether visual, performing, or literary, for their cultural value, and to honor and support traditional folk artists for their contribution to the national heritage by ensuring that the artistic skills which they have painstakingly cultivated and preserved are encouraged and passed on to future generations of Filipinos.\nThe objectives of this Act shall be as follows:\na. to acknowledge the importance of traditional folk artist as singular conduit between skills of the past and the future;\nb. to revitalize a community's artistic tradition thereby protecting a valuable facet of Philippine culture;\nc. to provide mechanisms for identifying and assisting qualified traditional folk artists to transfer their skills to the community; and\nd. to create opportunities for popularizing their works locally and internationally."}},{"id":"PH-H5843-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - For the purpose of this Act, Manlilikha ng Bayan shall mean a citizen or a group of citizens engaged in any traditional art uniquely Filipino, whose distinctive skills have reached such a high level of technical and artistic excellence and have been passed on to and widely practiced by the present generation in his/her community with the same degree of technical and artistic competence.\n\"Traditional Folk Art\" refers to expressions of distinctiveness and artistic quality created to serve a decorative and/or utilitarian or sociocultural functions of traditional folk artists commonly known for such works."}},{"id":"PH-H5843-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Criteria and Qualifications. - To become a Manlilikha ng Bayan, the candidate must satisfy the following minimum criteria:\na. Technical and creative skill - The candidate must possess a mastery of the tools and materials needed by the art, and must have an established reputation in the art as master and maker of works of extraordinary technical quality;\nb. Artistic quality - The work of the candidate must be outstanding aesthetically, and he/she must have consistently produced over a significant period, works of superior quality;\nc. Community tradition - The candidate must have transferred and/or willing to transfer to other members of the community, skills in the folk art for which the community has became nationally known;\nd. Folk art tradition - The candidate must have engaged in a folk art tradition that has been in existence and documented for at least fifty (50) years; and\ne. Character and integrity - As a precious treasure of the country the candidate must command the respect and admiration of the country for his character and integrity. The implementing agency may require additional criteria and qualifications in pursuance of the purposes of this Act."}},{"id":"PH-H5843-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Award and other Incentives. - The award given to the Manlilikha ng Bayan shall be called Gawad sa Manlilikha ng Bayan.\nIn addition, the following incentives shall be enjoyed:\na. Plaque/Medal - The awardee shall each receive a commemo- rative plaque and/or medal, a duplicate set of which is to be donated to and permanently displayed in the pertinent provincial museum or largest cultural center in order to broaden community awareness of the significance of our traditional folk arts and to accord them the recognition they richly deserve;\nb. An initial grant of One hundred thousand pesos (P100,000.00) and Ten thousand pesos (P10,000.00) a month thereafter for life, shall be given, unless the Commission after due hearing finds good reason to discontinue the grant arising from violations of pertinent terms and conditions herein stated.\nThis grant may be increased whenever circumstances so warrant provided that the increase shall not be given retroactive effect;\nc. Documentation - All surviving samples of works by the awardee shall be catalogued and photographed, and his/her work methods and shall likewise be documented;\nd. A vocational course using materials, tools, methods and designs of the awardee may be offered at the nearest arts and trades school through the cooperative efforts of the Department of Trade and Industry, the Department of Education, Culture and Sports, and a private foundation and/or private corporation, to effect the transfer of his/her skills and the preservation of folk art tradition;\ne. A feasibility study of converting the awardee's art into a specialized cottage industry in the awardee's province, preferably in the recipient's barangay or town, may be undertaken by the Department of Trade and Industry in collaboration with private investors; and\nf. The recipient shall be invited to Manila-based and regional cultural events that salute the importance of traditional folk arts in the Filipino cultural heritage;"}},{"id":"PH-H5843-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Duties and Responsibilities of Awardees. - The Manlilikha ng Bayan is a link between the past, in which his/her traditional folk art found fertile soil for growth, and the future, during which he/she seeks his/her art to be permanently sustained. It becomes his/her responsibility therefore to undertake the following:\na. to transfer the skills of his/her traditional folk art to the younger generation through apprenticeship and such other training methods as are found to be effective;\nb. to cooperate with the implementing agency, as provided for in Section 7 of this Act, in the promotion and propagation of his/her traditional folk arts; and\nc. to donate to the National Museum a sample or copy of his/her work."}},{"id":"PH-H5843-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Implementing Agency. -The Presidential Commission on Culture and Arts, created under Executive Order No. 118, dated January 30, 1987, shall develop and adopt a program to effectuate the provisions of this Act and promulgate such rules and regulations and criteria that will govern the selection of the Manlilikha ng Bayan.\nFor purposes of this Act, the Commission shall have the powers and functions:\na. to constitute and appoint panels of experts including, but not limited to, the nominees of the Office of Muslim Affairs, Office of Southern Cultural Communities and Office for Northern Cultural Communities in each of the traditional folk arts categories to assist the Commission in a thorough search for and fair awardees; such selection of traditional folk arts shall include but will not be to the following: weaving, woodcarving, metal-working, jewelry-making, embroidery, furniture making using indigenous materials, dance, song, instrumental folk music, folk literature, drama, boat-making, pottery-making, and other indigenous technology and architecture such as rice-terracing;\nb. to increase the monetary grant whenever circumstances so warrant provided that the increase shall not be given retroactive effect;\nc. to design, monitor and evaluate appropriate programs that shall ensure that the Manlilikhang Bayan transfers his/her skills to others, and to coordinate with pertinent agencies, public and private, for program implementation;\nd. to undertake measures that shall protect the intellectual/cultural property rights of the awardees;\ne. to promote the widest utilization and improvement of the awardees' design and patterns as well as their materials, tools and techniques in coordination with pertinent agencies, public and private;\nf. to undertake information dissemination programs intended to broaden community awareness of and instill pride in the achievements of the Manlilikha ng Bayan;\ng. to facilitate or undertake activities, public and private in coordination with the Department of Trade and Industry, the Department of Science and Technology, and the Department of Tourism, that shall make the efforts of the awardees not only aesthetically rewarding but also economically profitable; and\nh. to generate funds from the Government and the private sector for the implementation of the provisions of this Act."}},{"id":"PH-H5843-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Appropriations . - The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5843-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Privileges. - Pursuant to the existing provisions under the National Revenue Code (NRC) , as amended, and the Tariff and Customs Code of the Philippines (TCCP), as amended, any gifts or donations which shall be made to or for the use of the Philippine Commission on Culture and Arts, exclusively for the Manlilikha ng Bayan, shall be entitled to the following privileges:\na. Exemption from donor's tax pursuant to Section 94 (a) (3) of the NIRC, as amended;\nb. Deductibility of donations from the donor's gross income for purposes of computing taxable income in accordance with Section 29 and (h) of the NIRC, as amended; and\nc. Exemption from taxes and duties of donations from foreign countries subject to the provisions of Section 105 of the TCCP, as amended, and Section 103 of NIRC, as amended."}},{"id":"PH-H5843-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Repealing Clause . - All laws, issuances, decrees, or any part or parts thereof inconsistent with the provisions of this Act are deemed amended or repealed accordingly."}},{"id":"PH-H5843-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Effectivity Clause - This Act shall take effect fifteen (15) days after its publication in the Official Gazette or in a newspaper of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Recognition of National Living Treasures, Otherwise Known as the Manlilikha Ng Bayan, and the Promotion and Development of Traditional Folk Arts, Providing Funds Therefor, and for Purposes`","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5844"] = {"id":"PH-H5844","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7356_1992.html","fetchedAt":"2026-10-06","articleCount":27,"structureMode":"ARTICLE","title":{"zh":"设立国家文化艺术委员会、设立国家文化艺术捐赠基金并为其他目的法案","en":"An Act Creating the National Commission for Culture and the Arts, Establishing a National Endowment Fund for Culture and the Arts, and for Other Purposes","orig":"An Act Creating the National Commission for Culture and the Arts, Establishing a National Endowment Fund for Culture and the Arts, and for Other Purposes"},"level":"law","status":"active","topics":["culture"],"docNumber":"Republic Act No. 7356","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-03","completenessNote":"全文，共 27 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7356_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5844-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Law Creating the National Commission for Culture and the Arts\".\nTITLE I\nDECLARATION OF PRINCIPLES"}},{"id":"PH-H5844-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Culture as a Human Right. - Culture is a manifestation of the freedom of belief and of expression and is a human right to be accorded due respect and allowed to flourish."}},{"id":"PH-H5844-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"National Identity. - Culture reflects and shapes values, beliefs, aspirations, thereby defining a people's national identity. A Filipino national culture that mirrors and shapes Philippine economic, social and political life shall be evolved, promoted and conserved."}},{"id":"PH-H5844-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Culture of the People. - The Filipino national culture shall be: a) independent, free of political and economic structures which inhibit cultural sovereignty; b) equitable, effectivities creating and distributing cultural opportunities and correcting the imbalance that has long prejudiced the poor and other marginalized sectors who have the least opportunities for cultural development and educational growth; c) dynamic, continuously developing in pace with scientific, technological, social, economic and political changes both in national and international levels; d) progressive, developing the vast potential of all Filipinos as responsible change agents of society; and (e) humanistic, ensuring the freedom and creativity of the human spirit."}},{"id":"PH-H5844-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Culture by the People. - The Filipino national culture shall be evolved and developed by the people themselves in a climate of freedom and responsibility.\nNational cultural policies and programs shall be formulated which shall be: a) pluralistic, fostering deep respect for the cultural identity of each locality, region or ethno-linguistic locality, as well as elements assimilated from other cultures through the natural process acculturation; b) democratic, encouraging and supporting the participation of the vast masses of our people in its programs and projects; c) non-partisan, open to all people and institution, regardless of creed, affiliation, ideology, ethnic origin, age, gender or class, with no organized group or sector having monopoly of its services; and d) liberative, having concern for the decolonization and emancipation of the Filipino psyche in order to ensure the full-flowering of Filipino culture."}},{"id":"PH-H5844-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Culture for the People. - The creation of artistic and cultural products shall be promoted and disseminated to the greatest number of our people. The level of consciousness of our people about our own cultural values in order to strengthen our culture and to instill nationhood and cultural unity, shall be raised formally through the educational system and informally through extra-scholastic means, including the use of traditional as well as modern media of communication."}},{"id":"PH-H5844-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Preservation of the Filipino Heritage. - It is the duty of every citizen to preserve and conserve the Filipino historical and cultural heritage and resources. The retrieval and conservation of artifacts of Filipino culture and history shall be vigorously pursued.\nTITLE II\nORGANIZATION OF THE NATIONAL COMMISSION FOR CULTURE AND ARTS AND THE ESTABLISHMENT OF THE NATIONAL ENDOWNMENT FUND"}},{"id":"PH-H5844-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Commission. - A National Commission for Culture and Arts is hereby created to formulate policies for the development of culture and arts; implement these policies in coordination with affiliated cultural agencies; coordinate the implementation of programs of these affiliated agencies; administer the National Endowment Fund for Culture and Arts (NEFCA); encourage artistic creation within a climate of artistic freedom; develop and promote the Filipino national culture and arts; and preserve Filipino cultural heritage. The Commission shall be an independent agency. It shall render an annual report of its activities and achievements to the President and to Congress."}},{"id":"PH-H5844-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Composition. - The Commission shall be composed of the following members:\na. the Undersecretary of the Department of Education, Culture and Sports;\nb. the Undersecretary of the Department of Tourism;\nc. the Chairman of the House Committee on Culture;\nd. the Chairman of the Senate Committee on Culture;\ne. the President of the Cultural Center of the Philippines;\nf. the Executive Director of the National Historical Institute;\ng. the Director of the National Museum;\nh. the Director of the National Library;\ni. the Director of the Institute of Philippine Languages;\nj. the Director of the Records Management and Archives Office;\nk. the Executive Director of the Commission;\nl. the Head of the Subcommission on Cultural Communities and Traditional Arts;\nm. three (3) representatives from the private sector who shall be the elected heads of the three (3) Subcommission identified hereunder, namely: the Subcommission on Cultural Heritage, the Subcommission on the Arts, and the Subcomission on Cultural Dissemination. They shall be elected by the chairpersons of the national committees under their respective Subcommissions.\nThe Chairman of the Commission shall be elected by the members from among themselves."}},{"id":"PH-H5844-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Term of Office and Compensation. - The non- ex officio members of the Commission shall serve for a term of three (3) years, and shall not serve for more than two (2) successive terms. Non-ex officio members shall each receive a per diem of One thousand pesos (P1,000.00) for actual attendance in the meetings of the Commission, but not to exceed Five thousand pesos (P5,000.00) a month, and shall be reimbursed travel expenses incurred for actual attendance of meetings.\nEx officio members of the Commission shall receive representation and travel allowances (RATA) in accordance with rates recommended by the Department of Budget and Management."}},{"id":"PH-H5844-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Membership Restrictions. - During his/her term as member of the Commission, a Commissioner shall not be eligible for any grant, or such other financial aid from the Commission as an individual: Provided,however, That he/she may complete for grants and awards on the same level as other artists one (1) year after his/her term shall have expired."}},{"id":"PH-H5844-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Mandate. - The Commission is hereby mandated to formulate and implement policies and plans in accordance with the principles stated in Title I of this Act.\na. To encourage the continuing and balanced development of a pluralistic culture by the people themselves, it shall:\n1. encourage and ensure the exercise of the freedom of expression by eliminating all forms of censorship inimical to cultural and artistic growth and development without prejudice to the rights of other people to develop their own culture, or to the enhancement of a genuinely Filipino culture;\n2. extend financial and economic assistance such as subsidies, artist funds and social security to promote cultural development and protect artists and cultural workers;\n3. ensure the decentralization of opportunities for creative expression through the establishment of local culture and art centers in various regions, with resources needed for artistic cultural activities;\n4. extend recognition of artistic achievement through awards, grants and services to artists and cultural groups which contribute significantly to the Filipino's cultural legacy;\n5. promote the interests and welfare of artists and cultural workers by protecting their rights to intellectual and artistic properties as well as by associations which shall promote and protect the economic and moral rights of artists all over the country;\n6. encourage and support research into Philippine artistic traditions which may be adopted for the creation of contemporary forms;\n7. adopt measures and recommend legislations to protect the intellectual and artistic rights and properties of Filipino artists, cultural workers and other matters concerning culture and arts;\n8. explore and adopt the best possible structure of relationship between the public and the private sector at the local level, taking into account varying socio-cultural situations.\nb. To conserve and promote the nation's historical and cultural heritage, it shall:\n1. support, monitor and systematize the retrieval and conservation of artifacts of Filipino culture and history and all Filipino cultural treasures from all over the archipelago and other countries;\n2. encourage and support the study, recognition and preservation of endangered human cultural resources such as weavers, chanters, dancers, and other craftsmen as well as the conservation and development of such artistic, linguistic and occupational skills as are threatened with extinction;\n3. 3) support and promote the establishment and preservation of cultural and historical monuments, markers, names and sites;\n4. encourage and support the establishment and/or maintenance all over the country of museums, libraries, archives, private or public, as repositories, respectively of all cultural/historical artifacts and artistic creation, printed works, archival records and all other materials indispensable to the study and evaluation of Filipino culture and history;\n5. encourage the private sector to establish and maintain private museums and libraries;\n6. encourage and support scholarly research into and documentation of Philippine cultural traditions, arts and crafts, as well as significant cultural movements, achievements and personalities especially in the literary, visual and performing arts; and in mass media, as well as the various aspects of Filipino culture;\n7. encourage and support the writing of Philippine history from the Filipino perspective;\n8. encourage, support and systematize the audio-visual documentation of Filipino cultural expressions in the contemporary period.\nc. To ensure the widest dissemination of artistic and cultural products among the greatest number across the country and overseas for their appreciation and enjoyment, it shall, with the cooperation of the Departments of Education, Culture and Sports, Tourism, Interior and Local Government, Foreign Affairs and all other concerned agencies, public and private:\n1. cause to be established and developed an intensified arts education program at all levels of the educational system, public and private, to ensure meaningful arts integration across the school curriculum;\n2. encourage and support programs through publication, exhibition, production, performance, staging, and reproduction of original Filipino creations;\n3. coordinate and provide technical and/or financial assistance for cultural events and related activities such as cultural festivals, competitions, lectures, seminars, for a and symposia;\n4. encourage and monitor a comprehensive translation program which shall make works by Filipinos and selected foreign classics equally accessible to Filipino as well as international readers;\n5. promote the popularization of information about artistic and cultural achievements and programs, in coordination with government agencies and non-government organizations and institutions;\n6. reorient tourism programs to become an instrument for popular education of our people and others about the best of our heritage and creativity;\n7. undertake a systematic collection of statistical and other data which reflects the state of cultural conditions in the country, to serve as essential quantitative and qualitative basis for formulating cultural policies;\n8. create and support a sustained program of international cultural exchange, scholarships, travel grants and other forms of assistance;\n9. promulgate standards and guidelines for the protection and promotion of Filipino artists, cultural workers and creative works in other countries;\n10. encourage and support the continuous training of cultural workers and administrators by qualified trainors.\nd. To preserve and integrate traditional culture and its various creative expressions as a dynamic part of the national cultural mainstream, it shall;\n1. help set up or encourage, monitor and subsidize companion systems at the regional, provincial and local levels, intended to develop traditional cultures such as arts/crafts centers, preferably in community settings apart from the usual museum settings, where exponents of living arts and crafts can practice and teach their art and enrich contemporary designs;\n2. encourage and subsidize cultural research and the retrieval of cultural research information (e.g., folklore, dance, music, crafts) through the training of students, teachers, and cultural researchers, and their revitalization by practice and performance;\n3. ensure that the ultimate beneficiaries of all research efforts, tourism programs and other activities affecting cultural communities are the people and cultural communities are the people and cultural communities that are the subject of research, and that their cultures are nurtured rather than violated, damaged, or exploited;\n4. ensure that relevant information is made available to legislators who introduce laws with cultural implication;\n5. encourage and support the continuous training of cultural workers and administrators by qualified trainors.\ne. To ensure that standards of excellence are pursued in programs and activities implementing policies herein stated, it shall encourage and support continuing discussion and debate, through symposia, workshops, publications, etc., on the highest norms available in the matrix of Philippine culture."}},{"id":"PH-H5844-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Powers and Functions. - To carry out its mandate, the Commission shall exercise the following powers and functions:\na. encourage and facilitate the organization of a network of regional and local councils for culture and the arts, hereunder described, to ensure a broad nationwide, people-based participation in the formulation of plans, the enforcement of culture-related laws and regulations, the implementation of programs/projects and the review of funding requirements;\nb. establish a secretariat under an Executive Director for the administrative and day-to-day operations of the Commission;\nc. set up a system of networking and coordination with and among all existing government cultural agencies for the effective implementation of programs and activities;\nd. create committees and other mechanisms to help expedite the implementation of plans and strategies;\ne. call upon and coordinate with other government and non-government art and cultural institutions and agencies for assistance in any form;\nf. generate resources, both from the Government and private sectors, local, national and international, for its operation, as well as for the National Endowment Fund for Culture and Arts;\ng. receive and accept donations and other conveyances including funds, materials and services, by gratuitous title;\nh. administer the National Endowment Fund for Culture and Arts and give grants for the development, protection, preservation and dissemination of Philippine culture and arts, and designate a comptroller;\ni. prepare an annual budget of the Commission and submit the same to the President for inclusion in the annual General Appropriations Act;\nj. advise the President on matters pertaining to culture and arts, including the creation of a special decoration or award, for persons who have significantly contributed to the development and promotion of Philippine culture and arts;\nk. promulgate rules, regulations and undertake any and all measures as may be necessary to implement this Act;\nl. regulate activities inimical to preservation/conservation of national cultural heritage/properties."}},{"id":"PH-H5844-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The Secretariat. - The Commission shall organize a secretariat headed by an Executive Director. The Commission shall fix its staffing pattern, determine the duties, qualifications, responsibilities and functions as well as the compensation scheme for the positions to be created upon the recommendation of the Executive Director. The staffing pattern shall be approved and prescribed by the Commission within one hundred twenty (120) days from the approval of this Act."}},{"id":"PH-H5844-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The Subcommissions. - The Commission shall oversee the operation and maintenance of National Committees under the following Subcommissions;\na. Subcommission on Cultural Heritage, which shall cover but will not be limited to the following areas; libraries and information services, archives, museums, galleries, monuments and sites, and historical research;\nb. Subcommission on the Arts, which shall cover but will not be limited to the following areas; literary arts, visual arts, architecture, dramatic arts, broadcast arts, musical arts, dance, and film;\nc. Subcommission on Cultural Dissemination, which shall cover but will not be limited to the following areas; language and translation, cultural events, cultural education and information;\nd. Subcommission on Cultural Communities and Traditional Arts, which shall cover but will not be limited to the following areas; Agta culture and arts, cultures and arts of Northern cultural communities, Southern cultural communities, Muslim cultural communities, and lowland cultural communities."}},{"id":"PH-H5844-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Local, Provincial or Regional Councils. - The Commission may establish or coordinate with local, provincial or regional government or non-government councils/groups to promote, develop and implement programs and plans of the Commission."}},{"id":"PH-H5844-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The National Advisory Board. - The chairpersons of the National Committees shall form the National Advisory Board."}},{"id":"PH-H5844-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The National Cultural Agencies. - The Commission shall coordinate with the national cultural agencies including but not limited to the Cultural Center of the Philippines, the Institute of Philippine Languages, the National Historical Institute, the National Library, the National Museum, the Records Management and Archives Office. However, they shall continue operating under their respective charters or as provided by law where provisions therein are not inconsistent with the provisions of this Act. They shall serve as the national repository and/or showcase, as the case may be, of the best of Philippine culture and arts. For this purpose, these agencies shall submit periodic reports, including recommendations to the Commission."}},{"id":"PH-H5844-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Program Plans. - The Commission shall within three (3) months after having been officially constituted and finally staffed, adopt and immediately cause to be implemented in coordination with cultural agencies, a short-range program in support of relevant existing projects and activities; and within six (6) months, a long range three-year development program. This development program shall be developed and subjected to annual review and revision by the Commission in coordination with the councils as well as public and private cultural agencies and organizations."}},{"id":"PH-H5844-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"The National Endowment Fund for Culture and Arts. - A National Endowment Fund for Culture and Arts (the Fund) is hereby established exclusively for Philippine art and cultural programs, projects and activities all over the country.\na. The contribution to the Fund shall be the following:\n1. the amount of One hundred million pesos (P100,000,000.00) as seed capital shall be taken from the Philippine Amusement and Gaming Corporation (PAGCOR) fund at Five million pesos (P5,000, 000.00) per month for twenty (20) months; Provided, That no grant shall be awarded by the Commission except from the interest drawn from the funds: Provided, further, That no grant shall be awarded until after one (1) year from the organization of the Fund.\n2. 2) ten percent (10%) of the travel tax collection, the share to be taken from the annual allotment of the travel tax given to the Philippine Tourism Authority.\nb. Government corporations are hereby authorized to give grants to the Fund at their discretion, but not to exceed fifteen percent (15 %) of their unimpaired surplus;\nc. The private portion of the Fund shall be raised from donations and other conveyances including funds, materials, property and services, by gratuitous title;\nd. Contributions to the Fund shall be deductible for income tax purposes in accordance with the provisions of Section 29 (h) (2) (A) of the National Internal Revenue Code;\ne. For the sound and judicious management of the Fund, the Commission shall appoint a reputable government-accredited investment institution as Fund Manager, subject to guidelines promulgated by the Commission;\nf. The Commission shall be the administrator of the Fund, and as such, shall prepare implementing guidelines and decision-making mechanisms, subject to the following:\n1. unless otherwise stipulated by the private donor, only earnings of private contributions shall be used;\n2. no part of the seed capital of the Fund, including earnings, thereof, shall be used to underwrite overhead expenses for administration;\n3. not more than twenty percent (20%)) of the Government's annual contribution to the Fund shall be devoted to Administrative functions of the Commission; at least ten percent (10%) shall be earmarked as part of the Fund's capital, and the balance shall be used for its programs and projects;\n4. The Commission shall organize a separate staff, administratively independent of the secretariat, to be headed by a comptroller appointed by and directly responsible and accountable to the Commission;\n5. There shall be an external auditor to perform an annual audit of its performance;\n6. The Fund shall be exempt from pre-audit by the Commission on Audit."}},{"id":"PH-H5844-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Tax Exemption. - The Commission shall be exempt on all its income and duly obligations.\nAll materials that are reasonably necessary and are not manufactured or produced locally for the use of the Filipino artist shall be tax or duty free."}},{"id":"PH-H5844-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Revolving Fund. - The income of the Commission not exceeding the amount of Five hundred thousand pesos (P500,000.00) derived from the proceeds of sales of cultural items or publications shall be constituted as a revolving fund for the fabrication of such items or printing of such publications. Sales proceeds in excess of the aforementioned amount shall be remitted to the National Treasury and shall accrue to the General Fund.\nTITLE III\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H5844-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Transitory Provisions . -\na. All the personnel, properties, assets and liabilities of the Presidential Commission on Culture and Arts (PCCA) created by Executive Order No. 118, are hereby transferred to the Commission as its successor-in-interest.\nb. Within a period of one (1) year after the first meeting, of the Commission, it shall harmonize the policies of the cultural agencies referred to, but not limited to those enumerated in Section 18 of this Act, with those of the Commission as over-all policy-making and coordinating body, as herein indicated."}},{"id":"PH-H5844-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Notice or Consent Requirement. - If any organizational change herein authorized is of such substance or materiality as to prejudice third persons with rights recognized by law or contract such that notice to or consent of said persons or creditors is required to be made or obtained pursuant to any agreement entered into with any of such notice or consent requirement shall be complied with prior to the implementation of such organizational change."}},{"id":"PH-H5844-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Separability Clause . - Any portion or provision of this Act that may be declared unconstitutional shall not have the effect of nullifying other portions or provisions hereof as long as such remaining portions or provisions can still subsist and be given effect in their entirety."}},{"id":"PH-H5844-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Saving Clause. - All laws, rules, regulations, other issuances or parts thereof which are inconsistent with this Act are hereby repealed or modified accordingly. All provisions of Executive Order No. 118 not inconsistent with this Act shall however remain in full force and effect."}},{"id":"PH-H5844-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Effectivity . - This Act shall take effect immediately upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Creating the National Commission for Culture and the Arts, Establishing a National Endowment Fund for Culture and the Arts, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5845"] = {"id":"PH-H5845","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7357_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Penablanca市","en":"An Act Declaring Callao Cave and Its Premises Located At Callao, Municipality of Penablanca, Province of Cagayan, a Tourist Zone","orig":"An Act Declaring Callao Cave and Its Premises Located At Callao, Municipality of Penablanca, Province of Cagayan, a Tourist Zone"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7357","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7357_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5845-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Callao Cave and its premises located at Callao, Municipality of Penablanca, Province of Cagayan, is hereby declared a tourist zone. As such, it shall be accorded priority development by the Department of Tourism and shall be subject to the rules and regulations governing the development of tourist zones."}},{"id":"PH-H5845-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Department of Environment and Natural Resources and other government agencies concerned, shall, within one (1) year from the approval of this Act, prepare a tourism development plan for Callao Cave and its premises, which shall provide for the construction, improvement and/or maintenance of such appropriate facilities and infrastructure as shall encourage tourism in the area."}},{"id":"PH-H5845-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism, through the Philippine Tourism Authority, shall take immediate steps to implement said development plan and shall incorporate the same in the department's overall tourism development programs for the ensuing calendar year."}},{"id":"PH-H5845-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83"};
  FT["PH-H5846"] = {"id":"PH-H5846","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7358_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将佬沃市拉巴斯小学更名为Eulalio F. Siazon纪念小学的法案","en":"An Act Changing the Name of the La Paz Elementary School, Laoag City, to Eulalio F. Siazon Memorial Elementary School","orig":"An Act Changing the Name of the La Paz Elementary School, Laoag City, to Eulalio F. Siazon Memorial Elementary School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7358","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7358_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5846-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the La Paz Elementary School situated in Barangay La Paz, Laoag City, is hereby changed to Eulalio F. Siazon Memorial Elementary School."}},{"id":"PH-H5846-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports is hereby directed to promulgate and issue rules for the implementation of this Act."}},{"id":"PH-H5846-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the La Paz Elementary School, Laoag City, to Eulalio F. Siazon Memorial Elementary School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5847"] = {"id":"PH-H5847","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7359_1992.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":"废止 Don Mariano Marcos Memorial 国立大学（拉乌尼翁省 Bacnotan 市镇）蚕丝研究与发展中心，设立蚕丝研究与发展研究所并授权为此拨款的法案","en":"An Act to Abolish the Sericulture Research and Development Center At the Don Mariano Marcos Memorial State University, Municipality of Bacnotan, Province of La Union, and Create the Sericulture Research and Development Institute Authorizing the Appropriation of Funds Therefor, and for Other Purposes","orig":"An Act to Abolish the Sericulture Research and Development Center At the Don Mariano Marcos Memorial State University, Municipality of Bacnotan, Province of La Union, and Create the Sericulture Research and Development Institute Authorizing the Appropriation of Funds Therefor, and for Other Purposes"},"level":"law","status":"active","topics":["labor","education","culture"],"docNumber":"Republic Act No. 7359","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7359_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5847-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Sericulture Research and Development Center (hereinafter referred to as the SRDC) is hereby abolished. In its stead, the Sericulture Research and Development Institute (SRDI) (hereinafter referred to as the Institute) based at the Don Mariano Marcos Memorial State University (DMMMSU), in the Municipality of Bacnotan, Province of La Union, is hereby established."}},{"id":"PH-H5847-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All functions, equipment, facilities, supplies, records and personnel of the Sericulture Research and Development Center are hereby transferred to the Sericulture Research and Development Institute."}},{"id":"PH-H5847-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Institute shall have the following general powers and functions in line with the research and development programs of the Department of Science and Technology, Department of Agriculture, Department of Trade and Industry, National Economic and Development Authority, and the Don Mariano Marcos Memorial State University:\na. educate and train sericulturists;\nb. conduct researches; and\nc. extend technologies."}},{"id":"PH-H5847-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Institute shall have the following specific powers and functions:\na. develop productive, high yielding, good quality and pest/disease resistant varieties/strains of mulberry and silkworm;\nb. produce adequate certified mulberry planting materials and high quality silkworm eggs;\nc. develop efficient, economic and productive mulberry leaf production, preservation and utilization technologies;\nd. develop sound and productive silkworm rearing technology;\ne. develop the production and fabrication of reeling and re-reeling machineries suitable for rural use;\nf. develop effective mulberry and silkworm pests management strategies;\ng. evolve productive farming systems compatible with mulberry leaf production;\nh. develop efficient and effective local and international marketing systems;\ni. develop and implement appropriate and applicable technology packages and effective technology dissemination and utilization systems, particularly the conduct of training programs;\nj. upgrade skills of farmers and their families, development agents and extension workers through trainings, seminars and workshops on mulberry leaf production and storage, silkworm rearing for industrial and seed cocoon production, reeling and re-reeling, handloom weaving and other silk product and by-product utilization;\nk. coordinate with the Don Mariano Marcos Memorial State University in the conduct of higher and advanced sericulture degree programs;\nl. coordinate with other government/private agencies involved in the development of sericulture as a rural-based industry in the country."}},{"id":"PH-H5847-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Institute shall be headed by a Director who shall be responsible for the planning, implementation and supervision of the program and activities of the Institute. He shall be appointed by the Board of Regents of the Don Mariano Marcos Memorial State University upon recommendation of the University President. All other officers and employees shall be appointed by the Director of the Institute, in accordance with the Civil Service Law."}},{"id":"PH-H5847-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The plans and programs of the Institute shall be reviewed annually by an Advisory Board composed of:\na. the Secretary of Agriculture, as Chairman;\nb. the University President of the Don Mariano Marcos Memorial State University, as Vice Chairman;\nc. the Secretary of Trade and Industry, as Member;\nd. the Executive Director of the Philippine Council for Agriculture, Forestry and Natural Resources Research and Development (PCARRD), as Member;\ne. the Administrator of the Fiber Industry and Development Authority (FIDA), as Member;\nf. the Director, Philippine Textile Research Institute (PTRI), as Member;\ng. the Director, Sericulture Research and Development Institute (SRDI), as Member and Secretary;\nh. one (1) representative from private associations or cooperatives or producers of mulberry and silk cocoon, as Member; and\ni. one (1) representative from the local silk cloth processing and manufacturing industry, as Member."}},{"id":"PH-H5847-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The presence of five (5) members at the time of the meeting shall constitute a quorum: Provided, however, That the Chairman or, in his absence, the Vice Chairman shall preside."}},{"id":"PH-H5847-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"For the purpose of research and development activities of the Institute, researchers and support personnel of other related agencies may be detailed with the Institute upon the request of the Director of the Institute and subject to the approval of the Board of Regents of the university: Provided, That such personnel shall be paid honoraria for their services."}},{"id":"PH-H5847-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Institute is hereby authorized to plan, construct, develop, improve, acquire, or lease buildings, farms, fields and other facilities, to purchase machineries, equipment, materials and supplies locally or abroad as may be necessary to carry out its functions and objectives. Moreover, the Institute shall enjoy exemption from taxes and other duties in the importation of such machineries, equipment, materials and supplies required in its research and development programs, subject to the provisions of Section 105 (s) of the Tariff and Customs Code, Section 103 (f) of the National Internal Revenue Code and the provisions on automatic appropriations under the General Appropriations Act."}},{"id":"PH-H5847-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The main offices, experimental area and nursery of the Institute shall be situated at the Don Mariano Marcos Memorial State University campus at Bacnotan, La Union. The Institute may hereafter establish similar facilities in its other service areas in order to promote the development of sericulture in the countryside."}},{"id":"PH-H5847-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The amount of Twenty million pesos (P20,000,000.00) for the 1992 fiscal year budget is authorized to be appropriated from the Special Activities Fund of the President of the Republic of the Philippines, or from any other sources; and thereafter, the amounts required for its operation, maintenance, research and development activities shall be included in the annual General Appropriations Act and said amount to be disbursed to the Don Mariano Marcos Memorial State University, in the Province of La Union, exclusively for the capital and operational requirements of the Institute which shall include personnel services, maintenance and operating expenses, acquisition of equipment and laboratory facilities, development of experimental fields, and establishment of regional provincial, municipal sericulture projects as determined by the Director of the Institute, subject to the approval of the Board of Regents of said university."}},{"id":"PH-H5847-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"All expenditures and disbursement of funds made by the Institute in the conduct of its research and development activities shall be subject to existing auditing and accounting rules and regulations."}},{"id":"PH-H5847-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Any and all savings and income of the Institute shall constitute a revolving fund which shall not be reverted to the General Fund and which shall be used by the Institute to further pursue its objectives."}},{"id":"PH-H5847-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"All existing laws, rules and regulations or parts thereof inconsistent with the provisions of this Act are hereby repealed, superseded or modified accordingly: Provided, however, That nothing in this Act shall amend, modify or repeal the provisions of Republic Act No. 7160, otherwise known as the Local Government Code."}},{"id":"PH-H5847-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"This Act shall take effect after fifteen (15) days of its complete publication in the Official Gazette or in at least two (2) newspapers of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act to Abolish the Sericulture Research and Development Center At the Don Mariano Marcos Memorial State University, Municipality of Bacnotan, Province of La Union, and Create the Sericulture Research and Development Institute Authorizing the Appropriation of Funds Therefor, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5848"] = {"id":"PH-H5848","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7360_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"授权Orani区医院以五十张病床规模运营并为此拨款的法案","en":"An Act Authorizing the Orani District of Hospital to Operate At a Fifty-bed Capacity and Appropriating Funds Therefor","orig":"An Act Authorizing the Orani District of Hospital to Operate At a Fifty-bed Capacity and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7360","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7360_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5848-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Orani District Hospital in the Municipality of Orani, Province of Bataan, is hereby authorized to operate at a fifty-bed capacity."}},{"id":"PH-H5848-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The hospital's personnel complement shall be correspondingly increased to meet the operating needs of a fifty-bed hospital."}},{"id":"PH-H5848-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5848-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Authorizing the Orani District of Hospital to Operate At a Fifty-bed Capacity and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5849"] = {"id":"PH-H5849","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7361_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"将哥打巴托省立医院病床数由五十（50）张增至一百（100）张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Cotabato Provincial Hospital From Fifty (50) to One Hundred (100) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Cotabato Provincial Hospital From Fifty (50) to One Hundred (100) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7361","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7361_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5849-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Cotabato Provincial Hospital is hereby increased from fifty (50) to one hundred (100) beds."}},{"id":"PH-H5849-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5849-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the Department of Health is hereby authorized to issue all orders and circulars necessary in the implementation of this Act."}},{"id":"PH-H5849-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Cotabato Provincial Hospital From Fifty (50) to One Hundred (100) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5850"] = {"id":"PH-H5850","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7362_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"规定改善并增加邦板牙省Mabalacat急诊医院病床数并为此拨款的法案","en":"An Act Providing for the Improvement and Increase in the Bed Capacity of the Mabalacat Emergency Hospital in Pampanga, and Appropriating Funds Therefor","orig":"An Act Providing for the Improvement and Increase in the Bed Capacity of the Mabalacat Emergency Hospital in Pampanga, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7362","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7362_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5850-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act shall provide for the improvement and increase in the bed capacity of the Mabalacat Emergency Hospital in Pampanga from twenty-five (25) to fifty (50) beds."}},{"id":"PH-H5850-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5850-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Secretary of the Department of Health shall be responsible for the immediate implementation of this Act."}},{"id":"PH-H5850-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Improvement and Increase in the Bed Capacity of the Mabalacat Emergency Hospital in Pampanga, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5851"] = {"id":"PH-H5851","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7363_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"规定增加并改设卡皮斯省Dumarao市镇Dumarao医疗社区医院为25张床位的区医院，并为此拨款的法案","en":"An Act Providing for the Increase and Conversion of the Dumarao Medicare Community Hospital in the Municipality of Dumarao, Province of Capiz, Into a Twenty-five-bed Capacity District Hospital, and Appropriating Funds Therefor","orig":"An Act Providing for the Increase and Conversion of the Dumarao Medicare Community Hospital in the Municipality of Dumarao, Province of Capiz, Into a Twenty-five-bed Capacity District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7363","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7363_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5851-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dumarao Medicare Community Hospital in the Municipality of Dumarao, Province of Capiz, is hereby converted into a district hospital with an authorized bed capacity of twenty-five (25) beds."}},{"id":"PH-H5851-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5851-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Providing for the Increase and Conversion of the Dumarao Medicare Community Hospital in the Municipality of Dumarao, Province of Capiz, Into a Twenty-five-bed Capacity District Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5852"] = {"id":"PH-H5852","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7364_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将拉乌尼翁San Fernando的伊罗戈区域医院床位由150张增至200张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Ilocos Regional Hospital in San Fernando, La Union, From One Hundred Fifty (150) to Two Hundred (200) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Ilocos Regional Hospital in San Fernando, La Union, From One Hundred Fifty (150) to Two Hundred (200) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 7364","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7364_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5852-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Ilocos Regional Hospital in San Fernando, La Union, is hereby increased from one hundred fifty (150) to two hundred (200) beds."}},{"id":"PH-H5852-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law."}},{"id":"PH-H5852-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Ilocos Regional Hospital in San Fernando, La Union, From One Hundred Fifty (150) to Two Hundred (200) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5853"] = {"id":"PH-H5853","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7365_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将拉乌尼翁省Agoo市镇Doña Gregoria纪念医院床位增至125张并为此拨款的法案","en":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, to One Hundred Twenty-five (125) Beds, and Appropriating Funds Therefor","orig":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, to One Hundred Twenty-five (125) Beds, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["labor","health"],"docNumber":"Republic Act No. 7365","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-08","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7365_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5853-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The bed capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, is hereby increased from one hundred (100) to one hundred twenty-five (125) beds."}},{"id":"PH-H5853-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the lump-sum appropriations authorized for the purpose under the current General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5853-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Increasing the Bed Capacity of the Doña Gregoria Memorial Hospital in the Municipality of Agoo, Province of La Union, to One Hundred Twenty-five (125) Beds, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
