  FT["PH-H5876"] = {"id":"PH-H5876","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7388_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将伊莎贝拉Sta. Maria的Elvin Masigan市镇医院由10张床位的市镇医院扩建升级为25张床位的区医院，名称为Elvin Masigan区医院，并为此拨款","en":"An Act Expanding and Upgrading the Elvin Masigan Municipal Hospital in Sta. Maria, Isabela, From a Ten-bed Capacity Municipal Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Elvin Masigan District Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Elvin Masigan Municipal Hospital in Sta. Maria, Isabela, From a Ten-bed Capacity Municipal Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Elvin Masigan District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7388","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-10","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7388_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5876-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Elvin Masigan Municipal Hospital in Sta. Maria, Isabela, is hereby expanded and upgraded from a ten-bed capacity municipal hospital into a twenty-five-bed capacity district hospital, to be known as the Elvin Masigan District Hospital."}},{"id":"PH-H5876-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5876-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expanding and Upgrading the Elvin Masigan Municipal Hospital in Sta. Maria, Isabela, From a Ten-bed Capacity Municipal Hospital Into a Twenty-five-bed Capacity District Hospital, to Be Known as the Elvin Masigan District Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5877"] = {"id":"PH-H5877","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7389_1992.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"在塔克洛班市Marasbaras区设立国立中学，名称为Marasbaras国立中学，并为此拨款的法案","en":"An Act Establishing a National High School in the District of Marasbaras, Tacloban City, to Be Known as the Marasbaras National Hlgh School, and Appropriating Funds Therefor","orig":"An Act Establishing a National High School in the District of Marasbaras, Tacloban City, to Be Known as the Marasbaras National Hlgh School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7389","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-10","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7389_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5877-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established a national high school in the District of Marasbaras, Tacloban City, to be known as the Marasbaras National High School."}},{"id":"PH-H5877-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue the rules and regulations necessary to implement this Act."}},{"id":"PH-H5877-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5877-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Establishing a National High School in the District of Marasbaras, Tacloban City, to Be Known as the Marasbaras National Hlgh School, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5878"] = {"id":"PH-H5878","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7390_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将东萨马省吉波洛斯市镇马拉巴格描笼涯马拉巴格市镇中学的名称变更为马拉巴格中学的法案","en":"An Act Changing the Name of the Malabag Municipal High School in Barangay Malabag, Municipality of Giporlos, Province of Eastern Samar, to Malabag High School","orig":"An Act Changing the Name of the Malabag Municipal High School in Barangay Malabag, Municipality of Giporlos, Province of Eastern Samar, to Malabag High School"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7390","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-10","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7390_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5878-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Malabag Municipal High School in Barangay Malabag, Municipality of Giporlos, Province of Eastern Samar, is hereby changed to Malabag High School."}},{"id":"PH-H5878-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Malabag Municipal High School in Barangay Malabag, Municipality of Giporlos, Province of Eastern Samar, to Malabag High School","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5879"] = {"id":"PH-H5879","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7391_1992.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"将伊洛伊洛省 Dumangas 市镇 Purificacion Dolar Monfort 国立学校设为西米沙鄢科学技术学院分校并为其拨款的法案","en":"An Act Constituting the Purificacion Dolar Monfort National School in Barangay Purificacion D. Monfort in the Municipality of Dumangas, Province of Iloilo, Into a Branch of the Western Visayas College of Science and Technology in Iloilo City to Be Known as the Purificacion Dolar Monfort College, and Appropriating Funds Therefor","orig":"An Act Constituting the Purificacion Dolar Monfort National School in Barangay Purificacion D. Monfort in the Municipality of Dumangas, Province of Iloilo, Into a Branch of the Western Visayas College of Science and Technology in Iloilo City to Be Known as the Purificacion Dolar Monfort College, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7391","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-10","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7391_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5879-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Purificacion Dolar Monfort National School in Barangay Purificacion D. Monfort, Municipality of Dumangas, Province of Iloilo, is hereby constituted into a branch of the Western Visayas College of Science and Technology, Iloilo City, to be known as the Purificacion Dolar Monfort College. Said branch shall offer general secondary curriculum, vocational curriculum, and technical courses."}},{"id":"PH-H5879-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"All assets of the Purificacion Dolar Monfort National School, whether fixed or movable, and records are hereby transferred to the Western Visayas College of Science and Technology."}},{"id":"PH-H5879-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The teachers and other employees of the school shall be absorbed by the Western Visayas College of Science and Technology and shall continue in the service."}},{"id":"PH-H5879-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Secretary of Education, Culture and Sports shall be the necessary steps for the operation of the Western Visayas College of Science and Technology branch in the Municipality of Dumangas and the immediate implementation of this Act."}},{"id":"PH-H5879-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"All existing appropriations for the Purificacion Dolar Monfort National School are hereby transferred to the Western Visayas College of Science and Technology to be disbursed in accordance with the provisions of this Act. Thereafter, the sum necessary for the operation and maintenance of the College shall be provided for in the annual General Appropriations Act of the year following the approval of this Act."}},{"id":"PH-H5879-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Constituting the Purificacion Dolar Monfort National School in Barangay Purificacion D. Monfort in the Municipality of Dumangas, Province of Iloilo, Into a Branch of the Western Visayas College of Science and Technology in Iloilo City to Be Known as the Purificacion Dolar Monfort College, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5880"] = {"id":"PH-H5880","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7392_1992.html","fetchedAt":"2026-10-06","articleCount":30,"structureMode":"ARTICLE","title":{"zh":"修订经修正的第 2644 号共和国法即菲律宾助产法的法案","en":"An Act Revising Republic Act No. 2644, as Amended, Otherwise Known as the Philippine Midwifery Act","orig":"An Act Revising Republic Act No. 2644, as Amended, Otherwise Known as the Philippine Midwifery Act"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7392","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-10","completenessNote":"全文，共 30 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7392_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5880-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Philippine Midwifery Act of 1992\".\nARTICLE II - THE BOARD OF MIDWIFERY"}},{"id":"PH-H5880-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Composition. - There shall be a Board of Midwifery, hereinafter referred to as the Board, which shall be under the direct supervision of the Professional Regulation Commission (PRC). It shall be a collegial body composed of a chairman and four (4) members to be appointed by the President of the Philippines from among the recommendees of the Commissioner of the Professional Regulation Commission.\nThe Commission shall recommend three (3) registered midwives from the list submitted by the association of midwives; one (1) obstetrician from the list submitted by the association of obstetricians; and one (1) registered nurse-midwife from the list submitted by the association of midwives: Provided, That said associations are accredited in accordance with Presidential Decree No. 223: Provided, further, That the nominees submitted shall possess the appropriate qualifications prescribed in Section 3 hereof."}},{"id":"PH-H5880-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Qualifications and Disqualifications of the Board Members. -\na. Each member of the Board shall at the time of his appointment:\n1. be a citizen and resident of the Philippines;\n2. be of good moral character;\n3. be at least thirty (30) years of age; and\n4. not be a member of the faculty, whether full time, part time or lecturer, of any school, college or university where a regular course in midwifery is taught, and shall not have any pecuniary interest directly or indirectly, in such institution during his term of office as a Board member.\nb. The Chairman of the Board shall at the time of his appointment:\n1. be a registered obstetrician; and\n2. have at least ten (10) years practice as an obstetrician prior to his appointment.\nc. Three (3) members of the Board shall at the time of their appointment:\n1. be registered midwives;\n2. be degree holders, preferably in the field of health and social sciences; and\n3. have at least ten (10) years practice as midwives prior to their appointment, five (5) years of which are in supervisory positions.\nd. One (1) member of the Board shall at the time of his appointment:\n1. be a registered nurse-midwife; and\n2. have at least ten (10) years practice as a nurse-midwife."}},{"id":"PH-H5880-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Term of Office. - The Chairman and the four (4) members of the Board shall hold office for a term of three (3) years or until their successors shall have been appointed and duly qualified, without prejudice to reappointment for another term. Each member of the Board shall qualify by taking his/her oath of office before entering upon the performance of his/her duties."}},{"id":"PH-H5880-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Duties and Functions of the Board. - The Board shall have the following duties and functions:\na. to enforce the provisions of this Act;\nb. to administer oaths in accordance with the provisions of this Act;\nc. to issue and, after due investigation, suspend or revoke certificates or registration for the practice of midwifery;\nd. to investigate any violation of this Act or of the rules and regulations issued thereunder, as may come to the knowledge of the Board, and for this purpose, to issue subpoena and subpoena duces tecum to alleged violators or witnesses to secure their attendance in investigations or hearings, and the production of books, papers and documents in connection therewith and compel their attendance by the power of contempt;\ne. to conduct yearly board examinations to midwifery examinees under the supervision of the Commission;\nf. to look, from time to time, into the condition affecting the practice of midwifery in the Philippines and adopt such measures as may be deemed necessary for the maintenance of the standards and ethics of the profession; and\ng. to adopt an official seal to authenticate its official documents.\nThe Board shall exercise these powers and duties in accordance with Presidential Decree No. 223."}},{"id":"PH-H5880-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Compensation of Board Members. - The chairman and the members of the Board shall receive the same compensation granted to the Chairman and members of the boards of similar nature as provided for in the General Appropriations Act."}},{"id":"PH-H5880-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Removal of Board Members. - Any member of the Board may be removed from office by the President, upon the recommendation of the Professional Regulation Commission, for neglect of duty, incompetence or for unprofessional, immoral or dishonorable conduct, after having been given the opportunity to defend himself in a proper administrative investigation conducted by the Commission."}},{"id":"PH-H5880-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Supervision of the Board and Custodian of Its Records. - The members of the Board shall be under the general supervision of the Professional Regulation Commission. All records, including examination papers, examination results, minutes of deliberation, records of administrative cases and investigations of the Board shall be kept by the Commission."}},{"id":"PH-H5880-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Rules and Regulations. - Subject to the approval of the Commission, the Board shall set ethical and professional standards for the practice of midwifery and adopt such rules and regulations as may be necessary to carry out the provisions of this Act. Such standards, rules and regulations shall take effect thirty (30) days after publication in two (2) national newspapers of general circulation."}},{"id":"PH-H5880-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Annual Report. - The Board shall submit an annual report to the Commission at the end of each calendar year, giving a detailed report of its activities and proceedings during the year. Other information or data may be requested by the Commission as often may be necessary and practicable.\nARTICLE III\nEXAMINATION AND REGISTRATION OF MIDWIVES"}},{"id":"PH-H5880-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Examination Required. - All applicants for registration to the practice of midwifery in the Philippines shall be required to undergo an examination as required for in this Act."}},{"id":"PH-H5880-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Scope of Examinations. - The scope of examinations for the practice of midwifery shall consist of the following:\na. Infant care and feeding;\nb. Obstetrical anatomy and physiology;\nc. Principles of bacteriology as applied to midwife practice;\nd. Obstetrics;\ne. Midwifery procedures;\nf. Domiciliary midwifery;\ng. Community hygiene and first aid;\nh. Nutrition;\ni. Ethics of midwifery practice;\nj. Primary health care;\nk. Professional Growth and Development;\nl. Family planning; and\nm. Other subjects which the Board may deem necessary for addition or inclusion from time to time."}},{"id":"PH-H5880-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Prerequisite and Qualifications of Applicants for Examination. - In order to be admitted to the midwifery examination, an applicant shall, at the time of filing of his/her application therefor, establish to the satisfaction to the Board that he/she:\na. is in good health and of good moral character; and\nb. is a graduate of midwifery in a government recognized and duly accredited institution.\nAt the time of the issuance of a certificate of registration, the applicant shall be a citizen of the Philippines and at least eighteen (18) years of age."}},{"id":"PH-H5880-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Schools of Midwifery. - To be recognized as a duly accredited and legally constituted institution for midwifery training as provided in this Act, a school of midwifery shall have a permit from the Department of Education, Culture and Sports (DECS). The school shall have at least fifty (50) maternity beds and affiliated with an accredited hospital duly accredited by an authorized government agency or instrumentality.\nThe school shall have a minimum ratio of one (1) clinical instructor to twelve (12) students in the hospital and in the community.\nBefore allowing a student to graduate, the school shall satisfactorily show to the Department Education, Culture and Sports (DECS) or other authorized government agencies that the student has completed the course in midwifery as prescribed by the DECS or other duly authorized government agencies, and that during the training, the student has personally attended at least a total of twenty (20) deliveries in the hospital and in its domiciliary services."}},{"id":"PH-H5880-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Qualification of Faculty. - The faculty shall have academic preparation appropriate to teaching assignment, as follows:\na. At least a bachelor's degree holder or Doctor of Medicine (M.D.);\nb. Proof of competence in the field of specialization assigned to him; and\nc. A registered nurse or registered midwife in the Philippines with at least one (1) year of satisfactory teaching experience or one (1) year of efficient performance in maternity ward/community: Provided, That a registered midwife may be allowed to follow-up student midwives in the community ward provided she has at least two (2) years of experience in the area of assignment and has undergone training in the supervision of students."}},{"id":"PH-H5880-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Ratings in the Board Examination. - To be qualified as having passed the Board examination for Midwives, a candidate must obtain a general rating of seventy-five percent (75%) in the written test with no grade lower than fifty percent (50%) in any subject."}},{"id":"PH-H5880-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Report of the Results of Examination. - The Board shall, within one hundred twenty (120) days after the examination, report the ratings obtained by each candidate to the Commissioner of the Professional Regulations Commission."}},{"id":"PH-H5880-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Issuance of Certificate. - Certificate of Registration as midwife shall, upon payment of the required fees, be issued to any applicant who passes the examination. Every certificate of registration shall show full name of registrant, have a serial number, bear the signatures of the members of the Board, be attested by the Secretary of the Board, and be duly authenticated by the official seal of the Board.\nThe issuance of a certificate of registration by the Board to the registrant shall be evidence that the person named herein is entitled to all rights and privileges of a registered midwife until said certificate, for just cause, is suspended temporarily or revoked."}},{"id":"PH-H5880-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Registration of Nurse-Midwife. - Certification may be issued to registered nurses who pass the examination for midwives: Provided, That the nurse, before being allowed to take examination show evidence to the Board of having actually handled twenty (20) delivery cases as certified to by the director or chief of a duly registered or recognized hospital, or by the proper municipal, city, or provincial health officer."}},{"id":"PH-H5880-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Fees of Examination and Registration. - Applicants for examination for the practice of midwifery shall pay an examination fee as prescribed by the Professional Regulation Commission."}},{"id":"PH-H5880-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Inhibition Against Practice of Midwifery. - No person shall practice or offer to practice midwifery in the Philippines, as defined in this Act, without holding a valid certificate of registration and a professional license as midwife."}},{"id":"PH-H5880-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Foreign Reciprocity. - No midwife who is a citizen, subject or national of a foreign country shall be granted any of the rights and privileges under this Act unless he or she shows to the satisfaction of the Board that the country of which he or she is a citizen, subject or national, permits within its territorial limits on the same basis as the citizen, subject or national of such country: Provided, That the requisites for admission to midwifery school and for graduation in said country are substantially the same as those in this country."}},{"id":"PH-H5880-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Practice of Midwifery Defined. - The practice of midwifery consist in performing or rendering, or offering to perform or render, for a fee, salary, or other reward or compensation, services requiring an understanding of the principles and application of procedures and techniques in the supervision and care of women during pregnancy, labor and puerperium management of normal deliveries, including the performance of internal examination during labor except when patient is with antenatal bleeding; health education of the patient, family and community; primary health care services in the community, including nutrition and family planning in carrying out the written order of physicians with regard to antenatal, intra-natal and post-natal care of the normal pregnant mother in giving immunization, including oral and parenteral dispensing of oxytoxic drug after delivery of placenta, suturing perenial lacerations to control bleeding, to give intravenous fluid during obstetrical emergencies provided they have been trained for that purpose; and may inject Vitamin K to the newborn: Provided, however, That this provision shall not apply to students in midwifery schools who perform midwifery services under the supervision of the instructors, nor to emergency cases."}},{"id":"PH-H5880-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Refusal to Issue Certificate of Registration. - The Board shall refuse to issue a certificate of registration to any person convicted by a court of competent jurisdiction of any criminal offense involving moral turpitude, and to any person guilty of immoral or dishonorable conduct. The Board shall give the applicant a written statement setting forth the reason or reasons for its action, which statement shall be incorporated in the records of the Board."}},{"id":"PH-H5880-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Revocation and Suspension of Certificates. - The Board shall have the power to revoke or suspend the validity of a certificate of registration of a midwife for any of the causes mentioned in the preceding section, or for unprofessional conduct, malpractice, incompetence or serious ignorance or negligence, assisting or performing abortion in the practice of midwifery or for making use of fraud, deceit or false statements to obtain a certificate of registration.\nFrom the decision of the Board, appeal may be taken to the Professional Regulation Commission which decision shall be final."}},{"id":"PH-H5880-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"Reissuance of Revoked Certificates and Replacement of Lost Certificate. - The Board may, for reasons of equity and justice and upon proper application therefor, issue another copy of the certificate upon payment of dues, and in so doing, it may exempt the applicant from the requisite examination.\nARTICLE IV\nMISCELLANEOUS PROVISIONS"}},{"id":"PH-H5880-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Penal Provision. - Any person who shall practice midwifery in the Philippines within the meaning of this Act without a certificate of registration issued in accordance herewith, or any person presenting or using as his/her own certificate of registration of another, or any person giving any false or forged evidence to the Professional Regulation Commission in order to secure a certificate of registration, or any person using a revoked or suspended certificate of registration or any person assuming, using or advertising, as a registered midwife or a registered nurse-midwife or appending to his/her name the letters -R.M.- without having been conferred such title by the Professional Regulation Commission or advertising any title description tending to convey the impression that he/she is a registered midwife, shall be guilty of misdemeanor and shall, upon conviction, be sentenced to a fine of not less than Ten thousand pesos (P10,000.00) nor more than Thirty thousand pesos (P30,000.00), or to suffer imprisonment for a period of not less than two (2) years nor more than seven (7) years, or both such fine and imprisonment at the discretion of the court.\nThe aforementioned penalty shall likewise be imposed upon any person found guilty of violation of any rule and regulation issued pursuant to the provisions of this Act."}},{"id":"PH-H5880-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Repealing Clause . - Republic Act Numbered Two Thousand Six Hundred and Forty-four is hereby repealed and all laws, decrees, orders, instructions, rules and regulations and other issuances or parts thereof inconsistent with this Act are likewise repealed or amended accordingly."}},{"id":"PH-H5880-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Separability Clause . - If for any reason, any part or section of this Act shall be declared unconstitutional or invalid, other sections or provisions hereof which are not affected thereby shall continue to be in full force and effect."}},{"id":"PH-H5880-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon completion of its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Revising Republic Act No. 2644, as Amended, Otherwise Known as the Philippine Midwifery Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5881"] = {"id":"PH-H5881","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7393_1992.html","fetchedAt":"2026-10-06","articleCount":33,"structureMode":"ARTICLE","title":{"zh":"重组 Quedan 担保基金委员会，将其更名为 Quedan 与农村信贷担保公司，扩大其权力与资源以支持农民与农村企业，并为其他目的法案","en":"An Act Reorganizing the Quedan Guarantee Fund Board, Renaming It as Quedan and Rural Credit Guarantee Corporation, Enlarging Its Powers and Resources to Support Farmers and Rural Enterprises, and for Other Purposes","orig":"An Act Reorganizing the Quedan Guarantee Fund Board, Renaming It as Quedan and Rural Credit Guarantee Corporation, Enlarging Its Powers and Resources to Support Farmers and Rural Enterprises, and for Other Purposes"},"level":"law","status":"active","topics":["environment"],"docNumber":"Republic Act No. 7393","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 33 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7393_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5881-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Title . - This Act shall be known as the \"Quedan and Rural Credit Guarantee Corporation Act.\""}},{"id":"PH-H5881-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Declaration of Policy . - It shall be the policy of the State to accelerate the flow of investments and credit resources into the countryside so as to trigger the vigorous growth and development of rural productivity, employment and enterprises thereby generating more livelihood and income opportunities for the disadvantaged rural populace. Pursuant to this policy, there shall be set up a convenient credit-support mechanism and reliable guarantee system that shall effectively:\na. Improve the bankability of and access by rural workers, their cooperatives and small rural enterprises to formal credit institutions;\nb. Provide incentives for the banking sector to focus upon and enlarge the flow of credit funds and investments into the rural areas;\nc. Institutionalize the quedan or warehouse receipt and other negotiable instruments, evidencing stored agri-aqua produce in bonded warehouses, as the more convenient collateral for obtaining credit financing;\nd. Prioritize financing support to agrarian reform beneficiaries and their cooperatives for their production inputs and labor costs and their acquisition of farm equipment and post-harvest facilities;\ne. Support dynamic cooperativism, capital formation and savings mobilization among the rural populace;\nf. Increase farm income by promoting a system that by-passes unnecessary layers of middlemen and links producers more closely to end-users through auction markets, trading centers, consumer cooperatives and the like; and\ng. Harmonize and coordinate with all government institutions, nongovernmental organizations, private voluntary organizations, self-help groups and other aggrupations involved in providing support services to rural inhabitants."}},{"id":"PH-H5881-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Definition of Terms. - The following terms as used in this Act shall mean:\na. \"Corporation\" - The Quedan and Rural Credit Guarantee Corporation;\nb. \"Farmer\" - Any natural person whose primary livelihood is cultivation of land or the production of agricultural crops, livestock and aquaculture products, in small or commercial scale, either by himself or primarily with the assistance of his immediate farm household or workers, whether the land is owned by him or by another person, under a leasehold tenancy agreement or arrangement with the owner thereof;\nc. \"Fisherfolk\" - Refers to any natural person whose primary livelihood is fishing or the catching and/or gathering of other marine products, in small or commercial scale, either by himself or with the assistance of his immediate household or workers, whether the vessel, banca, and other equipment used is owned by him or by another person under lease or other arrangement with the owner thereof and there is no employer-employee relationship; and\nd. \"Cooperative\" - Refers to a duly registered association of persons, with a common bond of interest, who have voluntarily joined together to achieve a lawful common social or economic end, making equitable contributions to the capital required and accepting a fair share of the risks and benefits of the undertaking in accordance with universally accepted cooperative principles."}},{"id":"PH-H5881-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Reorganization. - The Quedan Guarantee Fun Board is hereby reorganized in accordance with the provisions of this Act, renamed as the Quedan and Rural Credit Guarantee Corporation and hereafter referred to as the Corporation. The Corporation is hereby attached to the Department of Agriculture pursuant to Administrative Order No. 59 (1988), but subject to the regulatory powers of the Securities and Exchange Commission insofar as allowed under Sections 9, 10 and 13 hereof."}},{"id":"PH-H5881-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Place of Business. - The Corporation shall have its principal place of business in Metro Manila and may establish as many branches or smaller units of organization in any part of the Philippines as may be necessary in carrying out efficiently and effectively its operations."}},{"id":"PH-H5881-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Existence. - The term of existence of the Corporation shall be fifty (50) years from the date of effectivity of this Act."}},{"id":"PH-H5881-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Authorized Capital Stock. - The authorized capital stock of the Corporation shall be Two billion pesos (P2,000,000,000) to be divided into two billion common and voting shares, with the par value of One peso (P1.00) per share, sixty percent (60%) thereof to be subscribed solely by the national government and/or government-owned or -controlled corporations and forty percent (40%) thereof solely by small farmers, fisherfolk, their cooperatives and other private investors: Provided, however, That the shares of the national government and government-owned or -controlled corporations may be sold to one another but not to private investors."}},{"id":"PH-H5881-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Subscription by National Government. - Upon the effectivity of this Act, the National Government shall be deemed to have subscribed to such number of shares of the Corporation equivalent in par value to, and considered paid for by the net assets of the Quedan Guarantee Fund Board, as determined and certified by the Commission on Audit within three (3) months from the effectivity hereof. Additional subscriptions, insofar as allowed by this Act, may be made by the National Government with the profits of the Corporation upon the majority vote of its governing Board in a meeting specially called for that purpose. The Secretary of Agriculture or his representative duly authorized in writing shall vote the shares owned by the national government. The chief executive officers of the government institutions referred to in Section 23 shall vote for their respective shareholdings."}},{"id":"PH-H5881-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Subscription by Private Investors. - No private person, natural or juridical, shall, directly or indirectly, by interlocking directorate or other forms of combinations, by trust, subscription, purchase, lease, mortgage, pledge, or other means of acquisition or encumbrance, own at any one time more than ten percent (10%) of the portion of the Corporation's authorized capital stock that can be subscribed solely by small farmers, fisherfolk, their cooperatives and other private investors. The Corporation in consultation with the Securities and Exchange Commission shall prescribe within sixty (60) days from the effectivity of this Act, implementing rules and regulations which will assure strict observance of the herein section by private investors and stock exchanges, stock-brokers, traders and personnel thereof, if the Corporation is listed in such exchanges for the trading of its shares therein under Section 10 hereof. Violation of any provision of the herein section or its implementing rules and regulations shall be punishable under Section 185 of the Revised Penal Code or, whenever applicable, the Anti-graft and Corrupt Practices Act."}},{"id":"PH-H5881-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Listing in Stock Exchanges. - The Corporation shall comply with all the requirements and shall apply for listing in stock exchanges for the purpose of trading its shares within one (1) year and six (6) months from the effectivity of this Act. Failure to comply with the provisions herein shall be prima facie evidence of bad faith on the part of the Corporation's personnel responsible therefor."}},{"id":"PH-H5881-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Corporate Powers. - The Corporation, as a body corporate, shall have the following powers and purposes:\na. Establish a credit-support mechanism for the benefit of farmers, fishermen, rural workers, cooperatives, retailers, wholesalers and primary processors of agricultural and aquatic commodities;\nb. lmplement a guarantee system to promote inventory financing of agri-aqua commodities; establishment of production and post-production facilities; acquisition of farm and fishery machineries, equipment and implements; and investment in production inputs and labor;\nc. Set up a system for accrediting the participation in the Corporation's various programs by borrowers, lending banks, financing institutions, bonding and insurance companies;\nd. Franchise-bonded warehouses intended for quedan inventory financing, issue and enforce rules and regulations therefor;\ne. Print and provide uniform negotiable quedan or warehouse receipt forms for the purpose of quedan financing which shall be serially numbered, on security notepaper, in specific quantity denominations of such unit of measurement of subject commodities; and shall contain the name and business address of the warehouseman, the variety, classification, moisture content and quality of the commodity deposited, the warranties of the warehouseman as prescribed by existing laws, rules and regulations, the charges and authorized liens on the stocks in deposit;\nf. Prescribe fees and charges for the Corporation's services; fix interest and penalty charges for delinquent accounts; and impose fines and sanctions for violations of its rules and regulations;\ng. Acquire by purchase or otherwise acquire ownership of and invest in, hold, sell or otherwise dispose of stocks or bonds of any interest in either or any obligation or evidence of indebtedness of any person, firm or corporation; and as owner of such stocks, bonds or interest therein, or other obligations or evidences of indebtedness, exercise the rights, powers and privileges or ownership, including the right to vote thereon or consent in respect thereto for any and all lawful purposes;\nh. Purchase or otherwise acquire, sell, lease, convey, mortgage or encumber and otherwise deal with any property, real or personal, or any interest therein;\ni. Act as a receiver;\nj. Adopt and use a corporate seal;\nk. Sue and be sued;\nl. Prescribe, repeal and alter its own bylaws; determine its operating policies and issue such rules and regulations as may be necessary and incidental to implement its various policies, programs and projects; and\nm. Carry on any lawful business whatsoever and do everything suitable, convenient and proper for the exercise of any of the foregoing powers and promote the interests of the Corporation or its properties."}},{"id":"PH-H5881-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Governing Board. - The affairs and business of the Corporation shall be directed, its properties managed and preserved, and its corporate powers exercised, unless otherwise provided in this Act, by a governing Board consisting of fifteen (15) members composed initially of the following: the Secretary of Agriculture, the Secretary of Agrarian Reform, the Governor of the Central Bank, the Administrator of the National Food Authority, the Chairman of the Cooperative Development Authority, the President of the Corporation and three (3) other members: a small farmer, a fisherfolk and an agricultural worker to be endorsed by the Department of Agriculture, the Department of Agrarian Reform and by the Cooperative Development Authority and approved by the other members of the governing Board after having been nominated by a nationally organized association of farmers, fisherfolk and farm workers, respectively. Said representatives shall serve for a term of one (1) year. Members of the governing Board who would proportionately represent the private investments in the Corporation shall be decided upon by the initial members of the governing Board.\nThe Secretary of Agriculture and the President of the Corporation, because of some governmental functions of the Corporation, shall be permanent ex officio chairman and vice-Chairman, respectively.\nThe chairman shall preside over the meetings of the governing Board where aside from voting regularly he shall vote to break a tie. He shall likewise preside over the stockholders' meetings.\nThe President of the Corporation, as vice-chairman of the Board, shall assist the chairman and act in his stead in case of the latter's absence or incapacity. In case of incapacity or absence of both the chairman and vice-chairman, the governing Board shall designate a temporary Chairman from among its members.\nThe governing Board shall prescribe the rules and regulations governing its deliberations and other official actions."}},{"id":"PH-H5881-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Election, Terms of Office of Elective Board Members. - The additional members of the governing Board to be elected by the initial members of the governing Board shall serve for a term of one (1) year each. The election shall be presided by the Board Chairman, which shall be held in Metro Manila, in a place accessible to the public, and shall be in accordance with provisions of the Corporation Code of the Philippines and other pertinent laws. The first election after the effectivity of this Act shall be held when the initial members of the governing Board shall have been duly constituted and twenty-five percent (25%) of the counterpart shares for private investors shall have been subscribed, the exact date, time and place to be determined by the governing Board then incumbent. The governing Board of the Corporation, in consultation with the Securities and Exchange Commission, shall prescribe the rules and regulations for the efficient and effective implementation of this section."}},{"id":"PH-H5881-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Specific Duties and Powers of Governing Board. - The governing Board shall have the following specific duties and powers:\na. Determine the general policies of the Corporation within the scope of its powers, objectives and financial resources;\nb. Approve and adopt annually the Corporation's budget at least three (3) months before the start of the fiscal period in conformity with the guidelines prescribed by the Department of Budget and Management, the Department of Finance and the Government Corporate Monitoring and Coordinating Committee; the Corporation's plan of operations for the year; as well as its medium- and long-term plans, programs and projects;\nc. Monitor the implementation of the Corporation's general policies, plans, budgets and projects;\nd. Upon the recommendation of its President, approve, reorganize or otherwise alter the position structure, staffing pattern, qualifications, powers and functions of the Corporation's officers and employees, in consultation with the Civil Service Commission and the Department of Budget and Management;\ne. Rationalize the rates of salaries, wages, allowances, per diems, consultant's fees, overtime pay and other forms of compensation, including gratuities and fringe benefits, which shall be determined in accordance with the position classification and compensation scheme or policy formulated under existing laws, rules and regulations and in consultation with the Civil Service Commission and the Department of Budget and Management, without prejudice to the compensation, fringe benefits and gratuities enjoyed by or provided for incumbent personnel at the effectivity of this Act;\nf. Approve, upon the recommendation of its president, the appointment of senior corporate officials in accordance with the pertinent provisions of the Civil Service Law, rules and regulations;\ng. Evaluate the financial reports of the Corporation and the comments of the Auditor thereon and, after approval such financial reports, consider each item thereof in respect of which the Auditor has expressed a reservation, or made an observation, or has refrained from expressing an opinion; and\nh. Submit to the President of the Philippines, the Congress of the Philippines, the Department of Finance, the Department of Budget and Management, the Department of Agriculture, and the Government Corporate Monitoring and Coordinating Committee, an annual report of the Corporation's operations which shall include the following audited financial statements: balance sheet or statement of assets and liabilities; income statement or statement of income and expenditures; and statement of sources and application of funds. Such report shall also include an analysis of any surplus or deficit of the Corporation and other additional statements and information necessary to make known the financial conditions and operations of the Corporation such as the outstanding domestic and foreign borrowings, the amount of government capital and/or dividend that will be credited to the Bureau of Treasury during the fiscal year, and appropriations needed to restore capital impairments, if any, subject to pertinent laws, rules and regulations; and such other reports and statements that the Government Corporate Monitoring and Coordinating Committee may prescribe."}},{"id":"PH-H5881-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"President. - The management of the day-today operations of the Corporation shall be vested in the President as its chief executive officer.\nNo person shall be appointed President by the governing Board unless he is in the government career service, is at least thirty-five (35) years of age and has expertise in banking, finance, economics, law, agriculture, business management, or public administration."}},{"id":"PH-H5881-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Powers and Duties of President. - The President of the Corporation shall have the following powers and duties:\na. Direct and manage the affairs and business of the Corporation;\nb. Implement the budget, policies, programs and projects approved by the governing Board;\nc. Enter into and execute, in behalf of the Corporation, all contracts and authorized transactions;\nd. Appoint, promote, remove, suspend or otherwise discipline for cause, any subordinate officer or employee of the Corporation pursuant to the Civil Service Law, rules and regulations: Provided, however, That with respect to officers with rank equivalent to or higher than vice-president, such action shall be subject to the approval of the governing Board;\ne. Ensure that the officers concerned prepare the annual and financial reports, including the analysis required in Section 14 hereof on or before the time fixed therein;\nf. Delegate any of his powers or duties to any officer of the Corporation as may be deemed expedient for its efficient and effective management; and\ng. Perform such other powers or duties as may be appropriately and reasonably assigned to him by the governing Board from time to time."}},{"id":"PH-H5881-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Solicitation of Grants. - The Chairman or President of the Corporation is hereby authorized, subject to the approval of the governing Board, to directly solicit, negotiate for and receive grants from any source, domestic or foreign, public or private, in accordance with existing laws.\nFor the purposes of this Act, grants shall include legacies, devises, gifts, donations, endowments and other transfers from any source, domestic or foreign, public or private, or the ownership and/or possession of real or personal properties, which transfers are free from any monetary consideration, it being understood that counterpart funding for such grants shall not be deemed as such consideration.\nWith respect to such grants, the following are hereby prescribed:\na. No grant shall be accepted if its terms and conditions are disadvantageous to the Corporation or the government;\nb. The disbursement or use by the Corporation of any cash grant shall be, pursuant to a special budget approved by the governing Board, in consultation with the Department of Budget and Management, and subject to accounting and auditing laws, rules and regulations;\nc. The Bureau of Customs shall give priority for the expeditious, safe, efficient and effective release from its premises of grants given to the Corporation under this Act;\nd. The Chairman or President of the Corporation may, in his sound discretion, deputize members of the Integrated Police, Philippine Constabulary and other security forces of the government to escort and/or guard the grants given to the Corporation under this Act in order to ensure their safe and speedy transportation, delivery and custody by the Corporation's representatives;\ne. Grants given to the Corporation under this Act shall be accorded utmost priority in transportation by national flag carriers and domestic common carriers; and\nf. Not later than forty (40) days from the start of or receipt thereof, the President shall submit to the Director General of the National Economic and Development Authority a report about the grants being negotiated for and/or received by the Corporation, specifying therein the peso value, general descriptions, sources, summaries of terms and conditions, purposes, and date of start of negotiation or receipt of such grants."}},{"id":"PH-H5881-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"Operating Principles. - The Corporation in the exercise of its powers shall be guided by the following operating principles:\na. The loanable value and guarantee cover under its various programs shall be scaled progressively in favor of rural-based cooperatives and micro-enterprises vis-a-vis small- and medium-size businesses:\nb. The rate of guarantee fees and charges shall be commensurate to the risk covered;\nc. Aggregate contingent liability, that is, its outstanding guarantee obligation at any given time, shall not exceed five (5) times its net worth;\nd. For agri-aqua commodities stored in bonded warehouses, the guarantee shall be their physical existence when covered by a quedan or warehouse receipt, chattel mortgage, deed of assignment, trust receipt, and other forms of collateral instruments on said commodities;\ne. For production and post-production facilities, farm machineries, equipment and implements, the guarantee shall be on the loan extended by a bank or lending institution on the basis of a mortgage thereon, without prejudice to the requirement for an additional or substitute collateral;\nf. For production inputs and labor, the guarantee shall be on the loan, provided that it is granted to rural cooperatives, without prejudice to the requirement for a counter-guarantee from nongovernmental organizations, or for some form of acceptable collaterals;\ng. The credit-support mechanism, as contemplated herein, may be in the form of assistance in client prospecting, credit evaluation, collateral appraisal, account monitoring, special time deposit, co-financing arrangement, co-guarantee, interest stabilization, liquidity access and other similar incentives for rural borrowers and lending institutions;\nh. The guarantee and credit-support system shall be oriented to promote capital formation and savings mobilization in the rural areas;\ni. Secondary trading market and liquidity access for participating banks and lending institutions, especially for those operating in small municipalities, shall be developed and promoted by the Corporation for its guaranteed loan papers; and\nj. Working relationships shall be harmonized with other government institutions, agencies and instrumentalities engaged in agricultural or rural development."}},{"id":"PH-H5881-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"Sovereign Guarantee. - In accordance with pertinent laws, rules and regulations, the Republic of the Philippines shall answer for the payment of guarantee obligations duly incurred by the Corporation under the provisions of this Act: Provided, however, That the Corporation's assets shall have been first fully exhausted to satisfy its guarantee obligations."}},{"id":"PH-H5881-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Compliance with Agri-Agra Law. - Investment by any banking institution in the authorized capital stock of the Corporation shall be considered compliance with Presidential Decree No. 717 (1975), otherwise known as the Agri-Agra Law, to the extent of its equity holdings in the Corporation. Likewise, loans extended by bank institutions to farmers, fishermen, cooperatives, rural workers and rural enterprises covered by the guarantees of the Corporation shall be deemed as compliance with the Agri-Agra Law. Rediscounting by secondary banks of originating banks' loan receivables having the guarantee cover of the Corporation shall likewise be deemed compliance with the same law."}},{"id":"PH-H5881-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"Protection for Corporation's Guarantees and Other Accommodations. - The provisions of any local, regional, national, special or general law to the contrary notwithstanding, securities on guarantees and/or accommodations granted by, or subrogated to, the Corporation or its predecessors-in-interest shall not be subject to attachment, execution or any other court process, nor shall they be included in the property of insolvent persons or institutions, unless all debts and obligations of the debtor to the Corporation and its predecessors-in-interest shall have been previously paid, including accrued interest, penalties, collection expenses, and other charges."}},{"id":"PH-H5881-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Dividend for Government Shareholdings. - The annual dividends that may be declared by the Corporation pertaining to the national government shareholdings shall be in the form of stock dividends in order to build up the capital base of the Corporation: Provided, however, That this provision shall not operate to prejudice the declaration of cash dividends to private stock-holders."}},{"id":"PH-H5881-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"Investment by Other Government Entities. - The Department of Agriculture, the Department of Agrarian Reform, the Technology and Livelihood Resource Center, the Philippine Amusement and Gaming Corporation, the Philippine National Bank, the Development Bank of the Philippines, the Land Bank of the Philippines, the Government Service Insurance System, the Social Security System, other government agencies and government-owned or -controlled corporations, are hereby authorized to invest in the capital stock of the Corporation in conformity with Sections 8, 10 and 12 hereof, and may, in a trust, provide the Corporation with credit or guarantee fund to service particular clients, cooperatives and rural aggrupations, as may be specified by any of these institutions, in accordance with their respective charters."}},{"id":"PH-H5881-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"Corporate Secretary. - The corporate secretary, who shall be a lawyer, appointed by the governing Board and under the supervision of its chairman, shall record the deliberations and other official actions of the governing Board and shall take custody of the records and other papers pertaining to it."}},{"id":"PH-H5881-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"Legal Affairs. - The Corporation shall have its own Legal Affairs Department to be beaded by the Corporate Legal Counsel who shall be appointed by the governing Board upon the recommendation of the President.\nIn appropriate cases, the Corporation may also avail of the legal services of any government legal office authorized to render such services to government-owned or -controlled corporations.\nThe Corporation may, upon the recommendation of its corporate legal counsel, deputize any member of its legal staff to act as special sheriff in foreclosure cases, in the sale or attachment the debtor's properties, and in the enforcement of court writs and processes in cases involving the Corporation. Such special sheriff of the Corporation shall make a report to the proper court on any action taken by him, which shall treat such action as if it were an act of its own sheriffs in all respects."}},{"id":"PH-H5881-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"COA Personnel and Expenditures. - The number of personnel to be assigned by the Commission on Audit in the Corporation and the concomitant expenses to be incurred in the performance of their duties shall be determined in such manner as to harmonize equitably the need of the Commission on Audit to undertake efficiently and effectively its constitutional powers and functions and the obligation of the Corporation to economize in the use of its funds, considering that it is the Corporation which shall defray the expenses for the audit of its operations. In case of disagreement between the Commission on Audit and the Corporation as to the reasonableness of the number of such personnel and their auditing expenditures, the opinion of the former shall prevail."}},{"id":"PH-H5881-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Transitory Provisions. - Upon the effectivity of this Act, the governing Board shall immediately be constituted and convened. All incumbent officers and employees of the Quedan Guarantee Fund Board shall continue in office as personnel of the Corporation without demotion in rank nor diminution in compensation and fringe benefits. The incumbent Executive Director of the Quedan Guarantee Fund Board shall be the President of the Corporation until a new President shall have been elected by the governing Board. The President shall, as soon as possible, prepare and submit to the governing Board such plans and programs which will ensure harmonious and effective transitional activities towards the full operations of the Corporation."}},{"id":"PH-H5881-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"Authority to Expand Personnel Complement. - In view of the expanded scope of the operations of the Corporation, it is hereby authorized to reorganize and expand its personnel complement, in consultation with the Civil Service Commission and in accordance with Section 14 hereof, in order to achieve efficiency and effectiveness in the delivery of its mandated services."}},{"id":"PH-H5881-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"Obligations and Liabilities. - All rights, claims and interests of the Quedan Guarantee Fund Board, upon the effectivity of this Act, shall be deemed transferred to the Corporation and all existing obligations and liabilities of the former shall be assumed by the latter."}},{"id":"PH-H5881-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Suppletory Application of Corporation Code. - Matters not provided for in this Act shall be governed by the Corporation Code of the Philippines in a suppletory character insofar as it is applicable."}},{"id":"PH-H5881-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"Separability. - Any portion or provision of this Act that may be unconstitutional or invalid shall not have the effect of nullifying other portions or provisions hereof as long as such portions or provisions can still subsist and be given legal force and effect in their entirety."}},{"id":"PH-H5881-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Repeal. - All laws, ordinances, rules, regulations and other issuances or parts thereof, contrary to or inconsistent herewith, are hereby repealed or modified accordingly."}},{"id":"PH-H5881-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"Effectivity . - This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Reorganizing the Quedan Guarantee Fund Board, Renaming It as Quedan and Rural Credit Guarantee Corporation, Enlarging Its Powers and Resources to Support Farmers and Rural Enterprises, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5882"] = {"id":"PH-H5882","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7395_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Mabuhay 广播系统公司在吕宋岛建设、安装、运营和维护无线电广播站并为其他目的法案","en":"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes","orig":"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7395","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7395_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5882-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Mabuhay Broadcasting System, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio broadcasting stations in the island of Luzon with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5882-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. -The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5882-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5882-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5882-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5882-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5882-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after the approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H5882-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title 11 of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5882-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Public Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5882-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5882-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise, or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5882-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5882-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5882-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5882-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5882-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Mabuhay Broadcasting System, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5883"] = {"id":"PH-H5883","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7396_1992.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"将依第 3246 号共和国法（经第 4546 号共和国法修正）授予 Universal 电信服务公司设立、运营国际与国内电信无线电台的特许权续展二十五（25）年","en":"An Act Renewing the Franchise Granted to the Universal Telecommunications Service, Incorporated, to Establish, Operate and Maintain Radio Stations for International and Domestic Telecommunications Under Republic Act No. 3246, as Amended By Republic Act No. 4546, to Another Twenty-five (25) Years From the Date of the Effectivity of This Act","orig":"An Act Renewing the Franchise Granted to the Universal Telecommunications Service, Incorporated, to Establish, Operate and Maintain Radio Stations for International and Domestic Telecommunications Under Republic Act No. 3246, as Amended By Republic Act No. 4546, to Another Twenty-five (25) Years From the Date of the Effectivity of This Act"},"level":"law","status":"active","topics":["investment","data","company"],"docNumber":"Republic Act No. 7396","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7396_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5883-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The franchise of the Universal Telecommunications Service, Incorporated, to establish, operate and maintain radio stations for international and domestic telecommunications under Republic Act No. 3246, as amended by Republic Act No. 4546, is hereby renewed to another twenty-five (25) years from the date of the effectivity of this Act."}},{"id":"PH-H5883-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of the effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5883-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or its assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title 11 of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5883-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5883-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise is subject to amendment or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5883-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"All the other provisions, terms and conditions contained in Republic Act No. 3246, as amended by Republic Act No. 4540, which are otherwise not affected thereby are hereby made integral parts of this Act."}},{"id":"PH-H5883-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5883-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Renewing the Franchise Granted to the Universal Telecommunications Service, Incorporated, to Establish, Operate and Maintain Radio Stations for International and Domestic Telecommunications Under Republic Act No. 3246, as Amended By Republic Act No. 4546, to Another Twenty-five (25) Years From the Date of the Effectivity of This Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5884"] = {"id":"PH-H5884","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7397_1992.html","fetchedAt":"2026-10-06","articleCount":17,"structureMode":"ARTICLE","title":{"zh":"授予 Sbs Radio Network, Inc. 在菲律宾建设、安装、运营和维护无线电广播站并为其他目的法案","en":"An Act Granting Sbs Radio Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Philippines and for Other Purposes","orig":"An Act Granting Sbs Radio Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Philippines and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 7397","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 17 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7397_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5884-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to SBS Radio Network, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio broadcasting stations in the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5884-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. -The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing stations or stations which may be established by law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5884-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5884-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation, or to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5884-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5884-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5884-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after the effectivity of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H5884-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5884-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. -The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations; but if any such speech, play, act or scene, or other matter should constitute a violation of the law or infringement of a private right, the grantee shall be free from any liability, civil or criminal, for such speech, play, act or scene, or other matter: Provided, That the grantee, during any broadcast and telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral; and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H5884-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H5884-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise nor the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Republic of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5884-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Public Ownership. - In adherence to the constitutional mandate, the herein grantee shall comply with the enabling law implementing for the purpose the democratization of ownership of all public utilities."}},{"id":"PH-H5884-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5884-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealing Clause . - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5884-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Broadcast Policy Law. - The grantee shall comply with such broadcast policy law as Congress may enact."}},{"id":"PH-H5884-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Report to the Congress of the Philippines. - The grantee shall submit an annual report to the Congress of the Republic of the Philippines with respect to its operations and/or in compliance with the terms and conditions of its franchise."}},{"id":"PH-H5884-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting Sbs Radio Network, Inc., a Franchise to Construct, Install, Operate and Maintain Radio Broadcasting Stations in the Philippines and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5885"] = {"id":"PH-H5885","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7398_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Corona International Inc. 在菲律宾全境设立、安装、维护、租赁和运营有线及无线电信系统用于国内与国际通信并为其他目的法案","en":"An Act Granting the Corona International Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems, Lines, Circuits and Stations Throughout the Philippines for Domestic and International Communications, and for Other Purposes","orig":"An Act Granting the Corona International Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems, Lines, Circuits and Stations Throughout the Philippines for Domestic and International Communications, and for Other Purposes"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 7398","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7398_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5885-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Corona International, Inc., hereunder referred to as the grantee, its successors or assigns a franchise to establish, install, maintain, lease and operate for commercial purposes and in the public interest wire and/or wireless telecommunications systems, lines circuits and stations throughout the Philippines with the corresponding transmitting and receiving stations at such places in the Philippines as it may consider necessary and convenient."}},{"id":"PH-H5885-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelenths or frequencies of the existing stations or other stations which may be established in accordance with law of other telecommunication services grantees without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as would maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5885-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission."}},{"id":"PH-H5885-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall conform to the ethics of honest enterprise and shall not use its stations for obscene or indecent transmissions or for the dissemination of deliberately false information or willful misrepresentation, or assist in subversive or treasonable acts."}},{"id":"PH-H5885-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Rates for Services. - The subscription charges and rates for services, excluding the sale or lease of equipment or units, that the grantee shall offer to the public shall be subject to the approval of the National Telecommunications Commis-sion or its legal successor."}},{"id":"PH-H5885-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or dis-turbance of peace and order, to take over and operate the sta-tions, transmitter systems, facilities and equipment of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations, transmitter systems, facilities and equipment during the period when they shall be so operated."}},{"id":"PH-H5885-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5885-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Public Ownership. - In compliance with the constitu-tional mandate to democratize ownership of public utilities, the herein grantee shall make public offering through the stock exchanges of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offerings."}},{"id":"PH-H5885-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Tax Provisions. -The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other person or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5885-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal government of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, systems, facilities and equipment of the grantee."}},{"id":"PH-H5885-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign the franchise herein granted nor the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5885-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Telecommunications Policy Law. - The grantee shall comply with and be subject to the provisions of a general telecommunications policy law that may hereafter be enacted."}},{"id":"PH-H5885-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5885-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5885-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its com-pliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5885-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after its publication in at least two (2) national newspapers of general circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Corona International Inc., a Franchise to Establish, Install, Maintain, Lease and Operate Wire And/Or Wireless Telecommunications Systems, Lines, Circuits and Stations Throughout the Philippines for Domestic and International Communications, and for Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5886"] = {"id":"PH-H5886","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7399_1992.html","fetchedAt":"2026-10-06","articleCount":16,"structureMode":"ARTICLE","title":{"zh":"授予 Aliw 广播公司在菲律宾全境安装、建设、运营和维护商业广播电视站的特许经营权法案","en":"An Act Granting the Aliw Broadcasting Corporation A Franchise To Install, Construct, Operate and Maintain Commercial Radio and Television Broadcasting Stations Throughout the Philippines","orig":"An Act Granting the Aliw Broadcasting Corporation A Franchise To Install, Construct, Operate and Maintain Commercial Radio and Television Broadcasting Stations Throughout the Philippines"},"level":"law","status":"active","topics":["investment","trade"],"docNumber":"Republic Act No. 7399","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 16 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7399_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5886-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Aliw Broadcasting Corporation, its successors or assigns and hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest radio and television broadcasting stations throughout the Philippines with the corresponding technological auxiliaries or facilities, special broadcast and other broadcast distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H5886-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result in the minimum interference on the wavelengths or frequencies of the existing stations or other stations which may be established in accordance with law without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H5886-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H5886-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide reasonable public service time to enable the Government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; promote public participation such as in community programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H5886-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - The President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, may temporarily take over and operate the stations of the grantee, temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or authorize the temporary use and operation thereof by any agency of the Government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H5886-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of the effectivity of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H5886-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. The grantee shall construct, complete and operate a television or radio station within two (2) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H5886-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio/television business transacted under this franchise by the grantee, its successors or assigns and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H5886-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Democratization of Ownership. - In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make public offerings through the stock exchange of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of effectivity of this Act: Provided, That no single entity shall be allowed more than five percent (5%) of the stock offerings."}},{"id":"PH-H5886-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations, systems and facilities and equipment of the grantee."}},{"id":"PH-H5886-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity, without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H5886-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause . - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H5886-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealing and Non-exclusivity Clause. - This franchise shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H5886-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"General Broadcast Policy. - The grantee shall comply with and be subject to the provisions of a general broadcast policy law that may hereafter be enacted."}},{"id":"PH-H5886-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Reportorial Requirement. - The grantee shall submit an annual report to the Congress of the Philippines on its compliance with the terms and conditions of the franchise and on its operations within sixty (60) days from the end of every year."}},{"id":"PH-H5886-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Granting the Aliw Broadcasting Corporation A Franchise To Install, Construct, Operate and Maintain Commercial Radio and Television Broadcasting Stations Throughout the Philippines","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5887"] = {"id":"PH-H5887","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7400_1992.html","fetchedAt":"2026-10-06","articleCount":19,"structureMode":"ARTICLE","title":{"zh":"进一步修订经修正的第 3591 号共和国法（即菲律宾存款保险公司宪章）并为其他目的法案","en":"An Act Further Amending Republic Act Numbered Three Thousand Five Hundred Ninety-one, As Amended, Otherwise Known As the Charter of the Philippine Deposit Insurance Corporation, and For Other Purposes","orig":"An Act Further Amending Republic Act Numbered Three Thousand Five Hundred Ninety-one, As Amended, Otherwise Known As the Charter of the Philippine Deposit Insurance Corporation, and For Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7400","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 19 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7400_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。 源文存在同号重出的条款（第 2 条）：该处官方页面确有两段均标同一 Section 号，本库照录其 `no` 值（不改动官方编号），条文 `id` 以 `_2`「_3」后缀保证唯一。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5887-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Section 2 of Republic Act No. 3591, as amended, is hereby further amended to read as follows:\n\""}},{"id":"PH-H5887-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The powers and functions of the Corporation shall be vested in and exercised by a Board of Directors which shall be composed of five (5) members as follows:\n\"(a) The Secretary of Finance who shall be the ex officio Chairman of the Board without compensation.\n\"(b) The Governor of the Central Bank, who shall be ex officio member of the Board without compensation.\n\"(c) The President of the Corporation, who shall be appointed by the President of the Philippines from either the Government or private sector to serve on a full-time basis for a term of six (6) years. The President shall also serve as vice chairman of the Board.\n\"(d) Two (2) members from the private sector, to be appointed for a term of six (6) years without reappointment by the President of the Philippines: Provided, That of those first appointed, the first appointee shall serve for a period of two (2) years.\n\"No person shall be appointed as member of the Board unless he be of good moral character and of unquestionable integrity and responsibility, and who is of recognized competence in economics, banking and finance, law, management administration or insurance, and shall be at least thirty-five (35) years of age. For the duration of their tenure or term in office and for a period of one year thereafter, the appointive members of the Board shall be disqualified from holding any office, position or employment in any insured bank.\n\"Whenever the Chairman of the Board is unable to attend a meeting of the Board, or in the event of a vacancy in the office of the Secretary of Finance, the President of the Corporation shall act as chairman.\n\"The presence of three (3) members shall constitute a quorum, and all decisions shall require a vote of a majority of the members present, there being a quorum.\n\"The members of the Board of Directors from the private sector, except the President shall receive a per diem for every board meeting attended, the amount of which shall be Five hundred pesos (P500.00) per meeting but not to exceed the sum of Two thousand pesos (P2,000.00) for every single month.\n\"The Board of Directors shall have the authority:\n\"1. To prepare and issue rules and regulations as it considers necessary for the effective discharge of its responsibilities;\n\"2. To direct the management, operations and administration of the Corporation;\n\"3. To appoint, establish the rank, fix the remuneration and remove any officer or employee of the Corporation for cause, subject to the Civil Service and pertinent compensation laws; and \"4. To authorize such expenditures by the Corporation as are the in the interest of the effective administration and operation of the Corporation.\""}},{"id":"PH-H5887-A2-d2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Section 2-A of the same Act is hereby amended to read as follows:\n\"Section 2-A. The President of the Corporation shall be the Chief Executive thereof and his salary shall be fixed by the President of the Philippines at a sum commensurate to the importance and responsibility attached to the position. The sum total of the salary of the President and the allowances and other emoluments which the Board of Directors may grant him shall be the ceiling for fixing the salary, allowances and other emoluments of all other personnel in the Corporation.\n\"The powers and duties of the President of the Corporation are:\n\"(a) To prepare the agenda for the meeting of the Board and to submit for the consideration of the Board the policies and measures which he believes to be necessary to carry out the purposes and provisions of this Act;\n\"(b To execute and administer the policies and measures approved by the Board;\n\"(c) To direct and supervise the operations and internal administration of the Corporation in accordance with the policies established by the Board. The President may delegate certain of his administrative responsibilities to other officers of the Corporation, subject to the rules and regulations of the Board;\n\"(d) To represent the Corporation, upon prior authority of the Board, in all dealings with other offices, agencies and instrumentalities of the Government and with all other persons or entities, public or private, whether domestic, foreign or international;\n\"(e) To authorize, with his signature, upon prior authority of the Board, contracts entered into by the Corporation, notes and securities issued by the Corporation, and the annual reports, balance sheets, profits and loss statements, and other documents of the Corporation. The signature of the President may be in facsimile wherever appropriate;\n\"(f) To represent the Corporation, either personally or through counsel, in all legal proceedings or actions;\n\"(g) To delegate, with the prior approval of the Board of Directors, his power to represent the Corporation, as provided in subsections (d) and (f) of this Section, to other officers of the Corporation; and \"(h) To exercise such other powers as may be vested in him by the Board.\n\"The President shall be assisted by a Vice President Vice and other officials whose appointment and removal for cause shall be approved and whose salary shall be fixed by the Board of Directors upon recommendation of the President of the Corporation. During the absence or temporary incapacity of the President, or in case of vacancy or permanent incapacity and pending the appointment of a new President of the Corporation by the President of the Philippines, the Vice President shall act as President and discharge the duties and responsibilities thereof.\""},"dupIndex":2},{"id":"PH-H5887-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 3, subsections (b), (c), (f), and (g) is hereby amended to read as follows:\n\"(b) The term 'Bank' and 'Banking Institution' shall be synonymous and interchangeable and shall include banks, commercial banks, savings bank, mortgage banks, rural banks, development banks, cooperative banks, stock savings and loan associations and branches and agencies in the Philippines of foreign banks and all other corporations authorized to perform banking functions in the Philippines.\"\n\"(c) The term 'receiver' includes a receiver, commission, person or other agency charged by law with the take charge of the assets and liabilities of a bank which has been forbidden from doing business in the Philippines, as well as the duty to gather, preserve and administer such assets and liabilities for the benefit of the depositors and creditors of said bank, and to continue into liquidation whenever authorized under this Act or other laws, and to dispose of the assets and to wind up the affairs of such bank.\"\n\"(f) The term 'deposit' means the unpaid balance of money or its equivalent received by a bank in the usual course of business and for which it has given or is obliged to give credit to a commercial, checking, savings, time or thrift account or which is evidenced by passbook, check and/or certificate of deposit, printed or issued in accordance with check and/or certificate of deposit, printed or issued in accordance with the Central Bank rules and regulations and other applicable laws, together with such other obligations of a bank, which, consistent with banking usage and practices, the Board of Directors shall determine and prescribe by regulations to be deposit liabilities of the Bank: Provided, That any obligation of a bank which is payable at the office of the bank located outside of the Philippines shall not be a deposit for any of the purposes of this Act or included as part of the total deposits or of insured deposit: Provided, further, That, subject to the approval of the Board of Directors, any insured bank which is incorporated under the laws of the Philippines which maintains a branch outside the Philippines may elect to include for insurance its deposit obligations payable only at such branch.\"\n\"(g) The term -insured deposit- means the net amount due to any depositor for deposits in an insured bank (after deducting offsets) less any part thereof which is in excess of One hundred thousand pesos (PIOO,000.00). Such net amount shall be determined according to such regulations as the Board of Directors may prescribe and in determining such amount due to any depositor, there shall be added together all deposits in the bank maintained in the same capacity and the same right for his benefit either in his own name or in the name of others: Provided, That the provisions of any law to the contrary notwithstanding, no owner/holder of any negotiable certificate of deposit shall be recognized as a depositor entitled to the rights provided in this Act unless his name is registered as owner/holder thereof in the books of the issuing bank.\""}},{"id":"PH-H5887-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Section 6, subsections (a) and (h), of the same Act is hereby amended to read as follows:\n\"(a) The assessment rate shall be determined by the Board of Directors: Provided, That the assessment rate shall not exceed one fifth (1/5) of one per centum (1%) per annum. The semi-annual assessment for each insured bank shall be in the amount of the product of one half (1/2) the assessment rate multiplied by the assessment base but it no case shall it be less than the amount of Two hundred fifty pesos (P250.00). The assessment base shall be the amount of the liability of the bank for deposits according to the definition of the term 'deposit' in and pursuant to subsection (f) of Section 3 without any deduction for indebtedness of depositors.\n\"The semi-annual assessment base for one semi-annual period shall be the average of the assessment base of the bank as of the close of business on March thirty-one and June thirty and the semi-annual assessment base for the other semi-annual period shall be the average of the assessment base of the bank as of the close of business on September thirty and December thirty-one: Provided, That when any of said days is a non-business day or legal holiday, either national or provincial, the preceding business day shall be used. The certified statements required to be filed with the Corporation under subsections (b) and (c) of this Section shall be in such form and set forth such supporting information as the Board of Directors shall prescribe. The assessment payments required from the insured banks under subsections (b) and (c) of this Section shall be made in such manner and at such time or times as the Board of Directors shall prescribe, provided the time or times so prescribed shall not be later than sixty (60) days after filing the certified statement setting forth the amount of assessment.\"\n\"(h) Should any insured bank fail or refuse to pay any assessment required to be paid by such bank under any provision of this Act, and should the bank not correct such failure or refusal within thirty (30) days after written notice has been given by the corporation to an officer of the bank citing this subsection, and stating that the bank has failed or refused to pay as required by law the insured status of such bank shall be terminated by the Board of Directors: Provided, That, after the lapse of thirty (30) days from the date when the written notice has been sent by registered mail, whether or not such notice has been actually received by the bank, the Corporation shall terminate the insured status of the bank. The bank shall give written notice of such termination to each of the depositors at his last address of record on the books of the bank and the Corporation shall publish the notice of such termination, less all subsequent withdrawals from any deposits of such depositor, shall continue to be insured for a period of ninety (90) days. No additions to any such deposits and no new deposits in such bank after the date of such termination shall be insured by the Corporation, and the bank shall not advertise or hold itself out as having insured deposits unless the same connection shall also state with equal prominence that such additions to deposits and new deposits made after such date are not so insured. In the event that such bank shall be closed on account of insolvency within the period of ninety (90) days, the Corporation shall have the same powers and rights with respect to such bank as in the case of an insured bank.\""}},{"id":"PH-H5887-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Section 7 of the same Act is hereby amended to read as follows:\n\"Section 7 (a). Whenever upon examination by the Corporation condition of any insured bank, it shall be disclosed that an insured bank or its directors or agents have committed, are committing or about to commit unsafe or unsound practices in conducting the business of the bank, or have violated, are violating or about to violate any provisions of any law or regulation to which the insured bank is subject, the Board of Directors shall submit the report of the examination to the monetary board to secure corrective action thereon. If no such corrective action is taken by the Monetary Board within sixty (60) days from the submission of the report, the Board of Directors shall, motu propio, institute corrective action which it deems necessary. The Board of Directors may issue a cease and desist order and require the bank or its directors or agents concerned to correct the practices or violations within sixty (60) days. However, If the practice or violation is likely to cause insolvency or substantial dissipation of assets or earnings of the bank, or is likely to seriously weaken the interests of its depositors and the Corporation, the period to take corrective action shall not be more than fifteen (15) days. The order may also include the imposition of fines provided in Section 16 (f) hereof. The Board of Directors shall duly inform the Monetary Board of the Central Bank of the Philippines of action it has taken with respect to such pratices or violations. If the bank violates the cease and desist order or fails to correct the practices or violations as required within the period prescribed herein, the corporation shall terminate the insured status of the bank on the Corporation, the bank and the depositors and their deposits shall be governed by Section 6 (h) hereof.\n\"(b) The actions and proceedings provided in the preceding subsection may be undertaken by the Corporation if, in its opinion, an insured bank or its directors or agents have violated, are violating or about to violate any provision of this Act or any order, rule or instruction issued by the Corporation or any written condition imposed by the Corporation in connection with any transaction with or grant by the Corporation.\""}},{"id":"PH-H5887-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Section 8 is hereby amended by adding a new paragraph to be designated as paragraph twelfth. Paragraph eighth is likewise amended. Paragraphs eighth and twelfth shall read as follows:\n\"Eighth -To conduct independent examinations and to require information and reports from banks, as provided in this Act, whenever deemed necessary by the Board of Directors: Provided, That to the extent practicable, said examinations shall maximize the efficient use of available relevant reports, information and findings, specifically from the Central Bank. The Board of Directors shall prescribe such regulations may be necessary to ensure the special nature and reasonable exercise of this power.\"\n\"Twelfth - To compromise, condone or release, in whole or in part, any of claim or settled liability to the Corporation, regardless of the amount involved, under such terms and conditions as may be imposed by the Board of Directors to protect the interest of Corporation.\""}},{"id":"PH-H5887-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Section 9, subsections (b) and (d) of the same Act is hereby amended to read as follows:\n\"(b) The Board of Directors shall appoint examiners who shall have power, on behalf of the Corporation to examine any insured bank. Each such examiner shall have the power to make a thorough examination of all the affairs of the bank and in doing so, ha shall have the power to administer oaths, to examine and take and preserve the testimony of any of the officers and agents thereof, and, to compel the presentation of books, documents, papers or records necessary in his judgment to ascertain the facts relative to the condition of the bank; and shall make a full and detailed report of the condition of the bank to the Corporation. The Board of Directors in like manner shall appoint claim agents who shall have the power to investigate and examine all claim for insured deposits and transferred deposits. Each claim agent shall have the power to administer oaths and to examine under oath and take and preserve testimony of any person relating to such claim.\"\n\"(d) The Corporation shall have access to reports of examination made by, and reports of condition made to the Central Bank of the Philippines or its appropriate supervising departments, and the Central Bank of the Philippines shall also have access to reports of examination made by, and reports of condition made to the Corporation: Provided, That the provisions of any law to the contrary nonwithstanding, the Corporation shall likewise have access to reports, findings and any other information derived from any special or general examination or inquiry conducted by the Central Bank in respect to bank fraud or serious irregularity in an insured bank: Provided, That, the Corporation shall use such reports and findings under similar terms and conditions prescribed by applicable laws on the Central Bank.\""}},{"id":"PH-H5887-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Section 9, subsection (e) of the same Act is hereby amended to read as follows:\n\"(e) Personnel of the corporation are hereby prohibited from:\n\"(1) being an officer, director, consultant, employee or stockholder, directly or indirectly, of any bank or banking institution except as otherwise provided in this Act.\n\"(2) receiving any gift or thing of value from any officer, director or employee thereof;\n\"(3) revealing in any manner, except under order of the court or authorized herein in such condition or business of any such institution. The prohibition shall not be held to apply to the giving of information to the Board of Directors or to any person authorized by either of them in writing to receive such information.\n\"Notwithstanding the provisions of this Section and Section 2, members of the Board of Directors and other personnel of the Corporation may become directors and officers of any bank and banking institution and of any entity related to such institution in connection with financial assistance extended by the Corporation to such institution and when in the opinion of the Board it is appropriate to make such a designation to protect the interest of the Corporation.\n\"Borrowing from any bank or banking institution by examiners and other personnel of the examination departments of the corporation shall be prohibited only with respect to the particular institution in which they are assigned, or are conducting an examination. Personnel of other departments, offices or units of the Corporation shall likewise be prohibited from borrowing from any bank or banking institution during the period of time that a transaction of such institution with the corporation is being evaluated, processed or acted upon by such personnel: Provided, however, That the Board may, at its discretion, indicate the position levels or functional groups to which the prohibition is applicable.\n\"Borrowing by all full-time personnel of the corporation from any bank or banking institution shall be secured and disclosed to the Board, and shall be subject to such further rules and regulations as the Board may prescribe.\""}},{"id":"PH-H5887-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The same Act is hereby amended by adding new sections after Section 9 thereof, to read as follows:\n\"Section 9-A The provisions of other laws, general or special, to the contrary notwithstanding, whenever it shall be appropriate for the Monetary Board of the Central Bank of the Philippines to appoint a receiver of any banking institution pursuant to existing laws, the Monetary Board shall give prior notice to and appoint the corporation as receiver.\n\"In addition to the powers of a receiver pursuant to existing laws, the Corporation is empowered to bring suits to enforce liabilities to or recoveries of the bank. Further, the Corporation may, upon its own responsibility, in the discretion of its Board of Directors and upon justifiable reasons, appoint and hire persons or entities of recognized competence in banking or finance as its deputies and assistants.\n\"The Corporation, its directors, officers and employees shall not be subject to any action, claim or demand for or in connection with any act done or omitted to be done by them in good faith in the exercise of their functions or in connection with the exercise of the powers under this Section and Sections 9-b, 9-c and 12 (c) of this Act.\n\"Section 9-B. Before any distribution of the assets of the closed bank in accordance with the preferences established by law, the Corporation shall periodically charge against said assets such reasonable receivership expenses and subject to approval by the proper court, such reasonable liquidation expenses, it has incurred as part of the cost of receivership/liquidation proceedings and collect payment therefor from available assets.\n\"Section 9-C. Cases not provided in Sections 9-A above including the filing of cases to modify, set aside or restrain any action of the Corporation therein shall be governed by Section 29 of R. A. 265, as amended.\""}},{"id":"PH-H5887-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Section 10, subsections (a-1,) (c) and (d) is hereby amended to read as follows:\n\"(a-1) The permanent insurance fund hereinabove created is hereby increased to Three billion pesos (P3,000,000,000 . 00) and for this purpose, such sum as be necessary is hereby appropriated from the General Fund: Provided, That the maximum amount of the insured deposit of any depositor is hereby increased to One hundred thousand pesos (P100,000.00).\"\n\"(c) Whenever an insured bank shall have been closed on account of insolvency payment of the insured deposits in such bank shall be made by the Corporation as soon as possible either BB[B(1) by cash or (2) by making available to each depositor a transferred deposit in another insured bank in an amount equal to the insured deposit of such depositor: Provided however, That the Corporation, in its discretion may require proof of claims to be filed before paying the insured deposits, and that in any case where the Corporation is not satisfied as to the viability of a claim for an insured deposit, it may require the final determination of a court of competent jurisdiction before paying such claim: Provided, further, That failure to settle the claim within six (6) months from the date of filing of the claim for insured deposit shall, upon conviction, subject the directors, officers or employees of the corporation responsible for the delay, to imprisonment from six (6) months to one (1) year: Provided, however, That the period shall not apply if the validity of the claim requires the resolution of issues of facts and or law by another office, body or agency including the case mentioned in the first proviso or by the Corporation together with such other office, body or agency.\n\"d) The Corporation, upon payment of any depositor as provided for in subsection (c) of this Section, shall be subrogated to all rights of the depositor against the closed bank to the extent of such payment. Such subrogation shall include the right on the part of the Corporation to receive the same dividends and payments from the proceeds of the assets of such closed bank and recoveries on account of stockholders' liability as would have been payable to the depositor on a claim for the insured deposits but, such depositor shall retain his claim for any uninsured portion of his deposit. All payments by the corporation of insured deposits in closed banks partake of the nature of public funds, and as such, must be considered a preferred credit similar to taxes due to the National Government in the order of preference under Article 2244 of the New Civil Code: Provided, further, That this preference shall be likewise effective upon liquidation proceedings already commenced and pending as of the approval of this Act, where no distribution of assets has been made.\""}},{"id":"PH-H5887-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Section 11, subsection (d) of the same Act is hereby amended to read as follows:\n\"(d) If, after the Corporation shall have given at least three (3) months notice to the depositor by mailing a copy thereof to his last known address appearing on the records of the closed bank, the depositor in the closed bank shall fail to file a claim for his insured deposit from the Corporation within eighteen (18) months after the Monetary Board of the Central Bank of the Philippines shall have ordered the closure of said bank pursuant to Section 29 of R. A. 265 as amended, all rights of the depositor against the Corporation with respect to the insured deposit shall be barred, and all rights of the depositor against the closed bank and its shareholders or the receivership estate to which the Corporation may have become subrogated, shall thereupon revert to the depositor: Provided, That the claimant shall enforce his duly-filed claim against the Corporation within one (1) year after the eighteen-month period heretofore mentioned. Thereafter, the Corporation shall be discharged from any liability on the insured deposit without prejudice to the rights of the claimant against the closed bank and its shareholders or the receivership estate: Provided, further, That when practicable, the Board of Directors may adopt other adequate means of notice to the depositor.\""}},{"id":"PH-H5887-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Section 12, subsection (c) of the same Act is hereby amended to read as follows:\n\"(c) When the Corporation has determined that an insured bank is in danger of closing, in order to prevent such closing, the Corporation, in the discretion of its Board of Directors, is authorized to make loans to, or purchase the assets of, or assume liabilities of, or make deposits in, such insured bank, upon such terms and conditions as the Board of Directors may prescribe, when in the opinion of the Board of Directors, the continued operation of such bank is essential to provide adequate banking service in the community or maintain financial stability in the economy.\n\"The authority of the Corporation under the foregoing paragraph to extend financial assistance to, assume liabilities of, purchase the assets of an insured bank may also be exercised in the case of a closed insured bank if the Corporation finds that the resumption of operations of such bank is vital to the interests of the community, or a severe financial climate exists which threatens the stability of a number of banks possessing significant resources: Provided, That the reopening and resumption of operations of the closed bank shall be subject to the prior approval of the Monetary Board.\n\"The Corporation may provide any Corporation acquiring control of, merging or consolidating with or acquiring the assets of an insured bank in danger of closing in order to prevent such closing or of a closed insured bank in order to restore to normal operations, with such financial assistance as it could provide an insured bank under this subsection: Provided, That, within sixty (60) days from date of assistance the Corporation shall submit a report thereof to the Monetary Board.\n\"In all cases, however, the Corporation, prior to the exercise of this power, shall determine that actual payoff and liquidation thereof will be more expensive than the exercise of this power. Finally, the Corporation may not use its authority under this subsection to purchase the voting or common stock of an insured bank but it can enter into and enforce agreements that it determines to be necessary to protect its financial interests.\""}},{"id":"PH-H5887-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Section 13 of the same Act is hereby amended to read as follows:\n\"The Corporation is authorized to borrow from the Central Bank of the Philippines and the Central Bank is authorized to lend the Corporation on such terms as may be agreed upon by the Corporation and the Central Bank, such funds as in the judgment of the Board of Directors of the Corporation are from time to time required for insurance purposes including those provided for in Section 12(c) of this Act: Provided, That any such loan as may be granted by the Central Bank shall be consistent with monetary policy: and Provided, further, That the rate of interest thereon shall be fixed by the Monetary Board but shall not exceed the treasury bill rate.\n\"When in the judgment of the Board of Directors the funds of the Corporation are not sufficient to provide for an emergency or urgent need to attain the purposes of this Act, the Corporation is likewise authorized to borrow money, obtain loans or arrange credit lines or other credit accom modations from any bank designated as depository or fiscal agent of the Philippine Government: Provided, That such loan shall be of short term duration.\""}},{"id":"PH-H5887-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Section 16, subsections (a), (d), (e) and (f) of the same Act is hereby amended to read as follows:\n\"(a) Every insured bank shall display at each place of business maintained by it a sign or signs, and shall include a statement to the effect that its deposits are insured by the Corporation in all its advertisements: Provided, That the Board of Directors may exempt from this requirement advertisements which do not relate to deposits or when it is impractical to include such statement therein. The Board of Directors shall prescribe by regulations the forms of such signs and the manner of use. For each day an insured bank continues to violate any provisions of this subsection or any lawful provisions of said regulations, it shall be subject to a penalty of not more than One thousand pesos (PI,000.00) which the Corporation may recover for its use: Provided, however, That the penalty of imprisonment for not more than one (1) year or a fine of not exceeding Twenty thousand pesos(P20, 000.00) or both, in the discretion of the court shall be imposed upon directors and officers of any bank not insured under the provisions of this Act which shall in any manner, advertise or hold itself out as having insured status for the purpose of making it appear that its deposits are insured with the Corporation.\"\n\"(d) The Corporation may require an insured bank to provide protection and indemnity against burglary, defalcation, losses arising from discharge of duties by, or particular acts of defaults of its directors, officers, or employees, and other similar insurable losses. The Board of Directors in consultation with the Central Bank, shall determine the bonding requirement as it refers to directors, officers and employers of the insured bank as well as the form and amount of the bond. Whenever any insured bank refuses to comply with any such requirement the Corporation may contract for such protection and add the cost thereof to the assessment otherwise payable by such bank.\"\n\"(e) Any assessment payable by an insured bank under this Act shall be subject to payment of interest computed from the date such assessment became due and payable and at the legal rate for loans as prescribed by law or appropriate authority and in case of willful failure or refusal to pay such assessment and interest thereon, there shall be added a penalty equivalent to twice the amount of interest payable as computed herein for each day such violations continue, which the interest and penalty the Corporation may recover for its use: Provided, That the penalty shall not be applicable under the circumstances stated in the provisions of subsection (b) of this Section.\"\n\"(f) The Board of Directors is hereby authorized at its discretion to impose upon insured banks, their directors and/or officers, for any willful delay in the submission of reports as required by law, rules and regulations; any refusal to permit examination in the affairs of the institution; any willful making of a false statement to the Corporation; any willful failure or refusal to comply with, or violation of any provision of this Act, or any order, instruction or regulations issued by the Corporation or any commission of irregularities, and/or conducting business in an unsafe or unsound manner as may be determined by the Board of Directors, a fine not exceeding One thousand pesos (P1,000.00) a day for each type of violation, the imposition of which shall be final and executory until reversed, modified or lifted by the Board of Directors.\""}},{"id":"PH-H5887-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Transitory Provisions. -\na. Authority to Reorganize. - In view of the new powers and functions herein provided, a reorganization of the Corporation is hereby authorized including adopting anew staffing pattern for effective and efficient exercise and performance of such powers and function. The formulation of the program of reorganization shall be completed as soon as possible and the full implementation of such program within eighteen (18) months after approval of this Act.\nb. Implementing Details. - Organization and Staffing of the Corporation. - Upon the effectivity of this Act, the Secretary of Finance, the incumbent President of the Corporation and the Governor of the Central Bank shall constitute the Chairman and members of the Board provided hereof. The President is hereby authorized subject to the approval of the Board of Directors as appropriate, to issue such orders, rules and regulations as may be necessary to implement the reorganization authorized under the preceding section which will involve the determination and adoption of (1) a new internal structure of the Corporation as reorganized down to the divisional, section or lowest reorganization levels; (2) a new staffing pattern including appropriate salary rates.\nThe provisions of any law to the contrary notwithstanding, in the implementation of the reorganization herein, and in the appointments to appropriate positions in the new staffing pattern of the Corporation, no preferential or priority rights shall be given to or enjoyed by any officer or personnel of the Corporation for appointment to any position in the new staffing pattern nor shall any officer or personnel be considered as having prior or vested rights with respect to retention in the Corporation or in any position as may have been created in its new staffing pattern, even if he should be the incumbent of a similar position therein.\nPending the completion of the personnel actions above provided and the issuance of the appropriate implementing orders, all incumbents shall continue to exercise their mutual functions, duties and responsibilities."}},{"id":"PH-H5887-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Any amount appropriated under the General Appropriations Act or any other appropriation or supplemental appropriation act shall be regularly released in accordance with the allotment system established under existing law."}},{"id":"PH-H5887-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"All acts or parts of act, presidential decrees, executive orders, administrative orders or parts thereof which are inconsistent with the provisions of this Act are hereby repealed."}},{"id":"PH-H5887-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Further Amending Republic Act Numbered Three Thousand Five Hundred Ninety-one, As Amended, Otherwise Known As the Charter of the Philippine Deposit Insurance Corporation, and For Other Purposes","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5888"] = {"id":"PH-H5888","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7401_1992.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"修订依第 3932 号共和国法授予 Concepcion 工业公司的特许权续展二十五年","en":"An Act Amending the Franchise Granted To the Concepcion Industries, Incorporated, Under Republic Act Numbered Thirty-nine Hundred and Thirty-two, Renewing the Term Thereof To Another Twenty-five Years From the Date of the Effectivity of This Act","orig":"An Act Amending the Franchise Granted To the Concepcion Industries, Incorporated, Under Republic Act Numbered Thirty-nine Hundred and Thirty-two, Renewing the Term Thereof To Another Twenty-five Years From the Date of the Effectivity of This Act"},"level":"law","status":"active","topics":["investment","company"],"docNumber":"Republic Act No. 7401","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-13","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7401_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5888-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The term of the franchise of the Concepcion Industries, Incorporated, or its successors or assigns, under Republic Act Numbered Thirty-nine hundred and thirty-two, is hereby renewed to another twenty-five years from the date of the effectivity of this Act.\nAny provision of Republic Act Numbered Thirty-nine hundred and thirty-two to the contrary notwithstanding, the grantee shall pay franchise, income and other taxes as provided for in Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto."}},{"id":"PH-H5888-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subject to the applicable rules and regulations of the National Telecommunications Commission, the grantee is hereby authorized to construct, install, operate, maintain, lease and manage radio stations and transmission facilities and equipment of whatever technology existing at present or may hereafter be invented, and to provide for a fee or engage in the operation of telecommunications services such as, but not limited to, value-added or enhanced services, trunked radio, and private networks services, whether one-way or two-way, fixed, land based or mobile communications, in the form of tone, voice, data, images or any other type of messages and impressions, to individuals, corporations and other juridical or natural entities, within the Philippines.\nNothing in the is provision shall be construed as allowing the grantee to engage in the business of operating a public switched telephone system or as a local exchange carrier, national toll service or inter-exchange carrier, international carrier, satellite communications or public broadcasting.\nThe services that are to be extended by the franchise shall not be used to enhance the candidacy or partisan political interest of any person or party."}},{"id":"PH-H5888-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All the other provisions, terms and conditions contained in Republic Act Numbered Thirty-nine hundred and thirty-two are hereby made integral parts of this Act."}},{"id":"PH-H5888-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The grantee is hereby given the option to assign or transfer this franchise to a wholly owned subsidiary for purposes of complying with the enabling law that may hereafter be enacted requiring public ownership in accordance with the constitutional mandate of broadening the base of ownership of public utilities. In such a case, the subsidiary shall be entitled to the franchise as if the same was originally granted to it."}},{"id":"PH-H5888-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Except as provided in the immediately preceding section, the grantee or its subsidiary shall not lease, assign, sell or transfer the franchise or the rights and interest therein to any person, firm, corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, sold or assigned, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, corporation or entity without the prior approval of the Congress of the Philippines. Any person, firm, corporation or entity to which this franchise is validly sold, transferred or assigned shall be subject to the same terms, conditions, restrictions and limitations of this Act."}},{"id":"PH-H5888-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The franchise hereby granted shall be subject to amendment, alteration or repeal by the Congress of the Philippines when the common good so requires."}},{"id":"PH-H5888-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"The grantee shall submit an annual report under oath on its operations to the Congress of the Philippines not later than April 30 of every year."}},{"id":"PH-H5888-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect fifteen (15) days after its in at least two (2) newspapers of national circulation."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Amending the Franchise Granted To the Concepcion Industries, Incorporated, Under Republic Act Numbered Thirty-nine Hundred and Thirty-two, Renewing the Term Thereof To Another Twenty-five Years From the Date of the Effectivity of This Act","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
