  FT["PH-H5891"] = {"id":"PH-H5891","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7404_1992.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":"将巴丹省迪纳卢皮汉市镇迪纳卢皮汉区医院的名称变更为Jose C. Payumo, Jr.,纪念医院的法案","en":"An Act Changing the Name of the Dinalupihan District Hospital in the Municipality of Dinalupihan, Province of Bataan, To Jose C. Payumo, Jr., Memorial Hospital","orig":"An Act Changing the Name of the Dinalupihan District Hospital in the Municipality of Dinalupihan, Province of Bataan, To Jose C. Payumo, Jr., Memorial Hospital"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7404","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-14","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7404_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5891-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Dinalupihan District Hospital in the Municipality of Dinalupihan, Province of Bataan, is hereby changed to Jose C. Payumo, Jr., Memorial Hospital."}},{"id":"PH-H5891-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Changing the Name of the Dinalupihan District Hospital in the Municipality of Dinalupihan, Province of Bataan, To Jose C. Payumo, Jr., Memorial Hospital","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["PH-H5892"] = {"id":"PH-H5892","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1992/ra_7405_1992.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"将南三宝颜省Mahayag市镇Mahayag社区医院由10张床位的社区医院扩建升级为25张床位的区医院，名称为Mahayag区医院，并为此拨款","en":"An Act Expanding and Upgrading the Mahayag Community Hospital in the Municipality of Mahayag, Province of Zamboanga Del Sur, From A Ten-bed Capacity Community Hospital Into A Twenty-five-bed Capacity District Hospital, To Be Known As the Mahayag District Hospital, and Appropriating Funds Therefor","orig":"An Act Expanding and Upgrading the Mahayag Community Hospital in the Municipality of Mahayag, Province of Zamboanga Del Sur, From A Ten-bed Capacity Community Hospital Into A Twenty-five-bed Capacity District Hospital, To Be Known As the Mahayag District Hospital, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7405","issuingBody":"Congress of the Philippines","promulgatedDate":"1992-04-14","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1992/ra_7405_1992.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5892-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Mahayag Community Hospital in the Municipality of Mahayag, Province of Zamboanga del Sur, is hereby expanded and upgraded from a ten-bed capacity community hospital into a twenty-five-bed capacity district hospital, to be known as the Mahayag District Hospital."}},{"id":"PH-H5892-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H5892-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p83","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1837-PH-7575","source":"An Act Expanding and Upgrading the Mahayag Community Hospital in the Municipality of Mahayag, Province of Zamboanga Del Sur, From A Ten-bed Capacity Community Hospital Into A Twenty-five-bed Capacity District Hospital, To Be Known As the Mahayag District Hospital, and Appropriating Funds Therefor","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
